-- ============================================================================
-- WUKIRTECH REAL RELATIONAL DATABASE SCHEMA & SEED DATA (SUPABASE POSTGRESQL)
-- Jalankan seluruh skrip ini di Supabase Dashboard -> SQL Editor -> Run
-- ============================================================================

-- 1. BERSIHKAN TABEL LAMA (HAPUS SEMUA DATA SEBELUMNYA)
DROP TABLE IF EXISTS public.products CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.events CASCADE;
DROP TABLE IF EXISTS public.news CASCADE;
DROP TABLE IF EXISTS public.vr_scenes CASCADE;
DROP TABLE IF EXISTS public.vr_tour_config CASCADE;
DROP TABLE IF EXISTS public.wukirtech_app_data CASCADE;

-- 2. BUAT STRUKTUR TABEL DATABASE
CREATE TABLE public.categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  description TEXT DEFAULT '',
  badge_color TEXT DEFAULT 'bg-primary/10 text-primary border-primary/30',
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  umkm TEXT NOT NULL,
  price TEXT NOT NULL,
  price_num INTEGER DEFAULT 0,
  description TEXT DEFAULT '',
  full_description TEXT DEFAULT '',
  image_url TEXT DEFAULT '/batik.jpg',
  images JSONB DEFAULT '[]'::jsonb,
  qris_image TEXT DEFAULT '',
  image_alt TEXT DEFAULT '',
  is_new BOOLEAN DEFAULT false,
  phone TEXT DEFAULT '628816413617',
  stock_status TEXT DEFAULT 'Tersedia',
  weight TEXT DEFAULT '350 gram',
  rating NUMERIC DEFAULT 4.9,
  highlights JSONB DEFAULT '[]'::jsonb,
  specifications JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.events (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  date TEXT NOT NULL,
  date_display TEXT DEFAULT '',
  time TEXT DEFAULT '',
  location TEXT DEFAULT '',
  venue_detail TEXT DEFAULT '',
  coordinates JSONB DEFAULT '[-7.9088, 110.4150]'::jsonb,
  google_maps_url TEXT DEFAULT '',
  image TEXT DEFAULT '',
  category TEXT DEFAULT 'Budaya',
  status TEXT DEFAULT 'Akan Datang',
  description TEXT DEFAULT '',
  full_description TEXT DEFAULT '',
  highlights JSONB DEFAULT '[]'::jsonb,
  tips TEXT DEFAULT '',
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.news (
  id TEXT PRIMARY KEY,
  tag TEXT DEFAULT '',
  category TEXT DEFAULT '',
  title TEXT NOT NULL,
  subtitle TEXT DEFAULT '',
  date TEXT DEFAULT '',
  read_time TEXT DEFAULT '',
  location TEXT DEFAULT '',
  author TEXT DEFAULT '',
  image TEXT DEFAULT '',
  gallery JSONB DEFAULT '[]'::jsonb,
  highlights JSONB DEFAULT '[]'::jsonb,
  summary TEXT DEFAULT '',
  content JSONB DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.vr_tour_config (
  id TEXT PRIMARY KEY DEFAULT 'default',
  title TEXT NOT NULL,
  subtitle TEXT DEFAULT '',
  theme TEXT DEFAULT '',
  start_scene_id TEXT DEFAULT '',
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE public.vr_scenes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT DEFAULT 'Wisata',
  image TEXT NOT NULL,
  description TEXT DEFAULT '',
  initial_yaw NUMERIC DEFAULT 0,
  initial_pitch NUMERIC DEFAULT 0,
  hotspots JSONB DEFAULT '[]'::jsonb,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. BERIKAN HAK AKSES SCHEMA & TABEL + AKTIFKAN RLS + REALTIME
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

GRANT ALL ON TABLE public.categories TO anon, authenticated, service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read categories" ON public.categories FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write categories" ON public.categories FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.categories;

GRANT ALL ON TABLE public.products TO anon, authenticated, service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read products" ON public.products FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write products" ON public.products FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.products;

GRANT ALL ON TABLE public.events TO anon, authenticated, service_role;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read events" ON public.events FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write events" ON public.events FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.events;

GRANT ALL ON TABLE public.news TO anon, authenticated, service_role;
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read news" ON public.news FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write news" ON public.news FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.news;

GRANT ALL ON TABLE public.vr_tour_config TO anon, authenticated, service_role;
ALTER TABLE public.vr_tour_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read vr_tour_config" ON public.vr_tour_config FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write vr_tour_config" ON public.vr_tour_config FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.vr_tour_config;

GRANT ALL ON TABLE public.vr_scenes TO anon, authenticated, service_role;
ALTER TABLE public.vr_scenes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read vr_scenes" ON public.vr_scenes FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Public Write vr_scenes" ON public.vr_scenes FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
ALTER PUBLICATION supabase_realtime ADD TABLE public.vr_scenes;

-- 4. STORAGE BUCKET UNTUK UPLOAD FOTO PRODUK, QRIS & PANORAMA 360
INSERT INTO storage.buckets (id, name, public)
VALUES ('wukirtech-media', 'wukirtech-media', true)
ON CONFLICT (id) DO NOTHING;

DROP POLICY IF EXISTS "Public access to wukirtech-media" ON storage.objects;
CREATE POLICY "Public access to wukirtech-media"
  ON storage.objects FOR ALL TO anon, authenticated
  USING (bucket_id = 'wukirtech-media')
  WITH CHECK (bucket_id = 'wukirtech-media');

