INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-1', 'Wedang Uwuh Bu Endang', 'Kuliner', 'UMKM Wukirsari', 'Rp20.000 / 10pcs', 20000, 'Minuman rempah hangat tradisional khas Imogiri yang menyehatkan tubuh dan kaya antioksidan.', 'Wedang Uwuh Bu Endang diracik menggunakan perpaduan rempah-rempah pilihan warisan turun-temurun dari Imogiri, Bantul. Terdiri dari kayu secang yang memberikan rona merah alami, jahe emprit bakar yang pedas menghangatkan, cengkeh, kayu manis, pala, serta daun pala dan serai wangi. Setiap kantong sudah dilengkapi dengan gula batu kristal higienis. Minuman ini sangat nikmat diseduh saat cuaca dingin, bermanfaat untuk meningkatkan stamina, meredakan masuk angin, melancarkan sirkulasi darah, dan kaya akan antioksidan alami.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/831f4e5dfdf72e4880aa6b7ee71b46b8.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/831f4e5dfdf72e4880aa6b7ee71b46b8.jpg","/uwuh.jpg"]'::jsonb, '', 'Tiga gelas wedang uwuh hangat disajikan di atas meja', false, '628816413617', 'Tersedia', '250 gram', 4.9, '["100% Rempah Alami Pilihan Tanpa Pengawet","Sudah Termasuk Gula Batu Alami Siap Seduh","Kaya Antioksidan & Menghangatkan Tubuh","Produksi UMKM Asli Binaan Desa Wukirsari"]'::jsonb, '[{"label":"Bahan Utama","value":"Secang, Jahe Emprit, Cengkeh, Kapulaga, Kayu Manis, Daun Pala"},{"label":"Isi Kemasan","value":"10 Bungkus Siap Seduh"},{"label":"Pemanis","value":"Gula Batu Kristal Alami Terpisah"},{"label":"Masa Simpan","value":"12 Bulan di tempat kering dan sejuk"},{"label":"Asal Wilayah","value":"Imogiri, Desa Wukirsari, Bantul, D.I. Yogyakarta"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-2', 'Handmade Batik Giriloyo', 'Kerajinan Tangan', 'Handmade batik', 'Rp750.000', 750000, 'Batik tulis Giriloyo dengan motif klasik tradisi keraton dan pewarnaan berkualitas.', 'Kain batik tulis otentik karya para pembatik perempuan Paguyuban Giriloyo, Wukirsari. Dibuat dengan metode canting tulis tradisional secara teliti selama berminggu-minggu menggunakan lilin malam alami dan kain mori primissima pilihan kelas satu. Motif klasik sarat dengan filosofi keraton Mataram yang melambangkan keharmonisan jiwa, keteguhan hati, dan kemakmuran hidup. Pewarnaan ramah lingkungan yang tahan luntur menjadikan kain ini koleksi berharga baik untuk busana formal maupun pusaka keluarga.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/3dd1c78d54698e2fa97c00ef157f5362.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/3dd1c78d54698e2fa97c00ef157f5362.jpg","/batik.jpg","/batik-1.jpg","/batik-2.png"]'::jsonb, '', 'Batik tulis Giriloyo dengan motif klasik', false, '628816413617', 'Tersedia', '350 gram', 5, '["100% Batik Tulis Canting Tangan Asli Giriloyo","Kain Mori Primissima Halus dan Sejuk","Pewarnaan Tahan Cuci & Tidak Luntur","Dilengkapi Sertifikat Autentikasi Pengrajin Wukirsari"]'::jsonb, '[{"label":"Teknik Pembuatan","value":"Full Tulis Canting Tangan (Dua Sisi)"},{"label":"Bahan Kain","value":"Katun Mori Primissima Super Halus"},{"label":"Ukuran Kain","value":"245 cm x 115 cm (Standar Busana / Kemeja)"},{"label":"Lama Pengerjaan","value":"3 - 4 Minggu per helai kain"},{"label":"Motif","value":"Klasik Wahyu Tumurun / Sidomukti Giriloyo"},{"label":"Asal Wilayah","value":"Kampung Batik Giriloyo, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-3', 'Wayang Kulit Arjuna', 'Seni Pertunjukan', 'Ituk Wayang', 'Rp600.000', 600000, 'Wayang kulit tokoh Arjuna buatan pengrajin Pucung dengan tatah sungging halus kulit kerbau pilihan.', 'Mahakarya seni wayang kulit khas Dusun Pucung, Desa Wukirsari—sentra tatah sungging wayang kulit terkemuka di Indonesia. Tokoh ksatria penengah Pandawa, Raden Arjuna, dipahat dengan ketelitian ornamen tatahan yang rumit dan pewarnaan (sungging) emas prada bertingkat. Menggunakan kulit kerbau kering berkualitas tinggi yang tidak mudah melengkung, dipadukan dengan gapit (tangkai) dari tanduk kerbau asli yang kokoh dan berkilau alami. Sangat cocok sebagai hiasan dinding prestisius, hadiah kehormatan, maupun instrumen pagelaran wayang.', '/wayang.jpeg', '["/wayang.jpeg","https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/3dd1c78d54698e2fa97c00ef157f5362.jpg"]'::jsonb, '', 'Wayang kulit dari Pucung', true, '628816413617', 'Tersedia', '400 gram', 4.8, '["Kulit Kerbau Asli Berkualitas Super Kuat","Tatah Sungging Halus dengan Sentuhan Prada","Gapit Tanduk Kerbau Asli Kokoh & Eksklusif","Dibuat Langsung oleh Maestro Pengrajin Pucung"]'::jsonb, '[{"label":"Tokoh Wayang","value":"Raden Arjuna (Janaka)"},{"label":"Material Wayang","value":"Kulit Kerbau Pilihan 100%"},{"label":"Material Gapit","value":"Tanduk Kerbau Asli (Bukan Plastik)"},{"label":"Tinggi Wayang","value":"Kurang lebih 65 cm (dengan tangkai)"},{"label":"Teknik Pewarnaan","value":"Sungging Manual Cat Pigmen & Prada Emas"},{"label":"Asal Sentra","value":"Dusun Pucung, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-4', 'Kipas Tangan Zainal', 'Kerajinan Tangan', 'Zainal Kipas', 'Rp25.000', 25000, 'Kipas tangan ramah lingkungan dari bambu halus berpadu kain motif batik khas Wukirsari.', 'Kipas tangan lipat ramah lingkungan yang memadukan bilah bambu apus pilihan yang dihaluskan tanpa serabut dengan bentangan kain perca bermotif batik khas Wukirsari. Ringan, praktis dibawa di dalam tas, serta memberikan hembusan angin sejuk yang nyaman. Merupakan salah satu produk ekonomi kreatif ramah lingkungan yang banyak digemari sebagai cinderamata pernikahan, oleh-oleh wisatawan desa, maupun suvenir acara kenegaraan.', '/kipas.jpg', '["/kipas.jpg","/batik-1.jpg"]'::jsonb, '', 'Kipas bambu dengan motif batik', true, '628816413617', 'Tersedia', '80 gram', 4.7, '["Bilah Bambu Pilihan Halus & Tidak Mudah Patah","Kain Perca Batik Otentik Ramah Lingkungan","Bisa Dipesan Custom Nama untuk Souvenir Acara","Harga Terjangkau Kualitas Pengrajin Lokal"]'::jsonb, '[{"label":"Bahan Rangka","value":"Bambu Apus Alami Halus"},{"label":"Bahan Daun Kipas","value":"Kain Katun Motif Batik Wukirsari"},{"label":"Diameter Bentang","value":"38 cm (Saat Dibuka)"},{"label":"Panjang Rangka","value":"21 cm (Saat Dilipat)"},{"label":"Kapasitas Pesanan","value":"Menerima Pesanan Massal (>500 pcs)"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-5', 'Thiwul Mbak Iswati', 'Kuliner', 'Mbak Iswati', 'Rp15.000 / porsi', 15000, 'Makanan tradisional olahan singkong manis gurih dengan taburan kelapa parut segar.', 'Thiwul Mbak Iswati menyajikan cita rasa nostalgia kuliner tradisional khas Imogiri dan perbukitan Wukirsari. Diolah dari gaplek singkong fermentasi alami yang ditumbuk menjadi butiran tepung pulen, kemudian dikukus bersama gula jawa murni nira kelapa lokal. Disajikan dengan parutan kelapa muda gurih berbumbu sedikit garam laut alami. Teksturnya kenyal, manis legit, bebas gluten, dan mengenyangkan.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg","/sawah.jpg"]'::jsonb, '', 'Thiwul instan disajikan dengan kelapa parut', true, '628816413617', 'Tersedia', '300 gram', 4.9, '["100% Olahan Singkong Alami Bebas Pengawet","Pemanis Alami Gula Kelapa Jawa Murni","Makanan Sehat Rendah Glikemik & Bebas Gluten","Bisa Dipesan Instan Kering untuk Oleh-Oleh Jarak Jauh"]'::jsonb, '[{"label":"Bahan Baku","value":"Singkong Gaplek Pilihan, Gula Jawa Kelapa, Kelapa Parut"},{"label":"Pilihan Kemasan","value":"Siap Santap (Besek Daun Pisang) / Kemasan Instan Kering"},{"label":"Ketahanan","value":"1 Hari (Matang Segar) / 6 Bulan (Varian Instan Kering)"},{"label":"Saran Penyajian","value":"Nikmat disantap hangat bersama teh nasgitel atau kopi lokal"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-6', 'Batik Sungsang', 'Kerajinan Tangan', 'Paguyuban Batik Giriloyo', 'Rp900.000', 900000, 'Batik Sungsang dengan motif abstrak dan filosofi mendalam dalam pewarnaan cerah modern.', 'Koleksi eksklusif batik tulis kontemporer dari Paguyuban Batik Giriloyo yang mengangkat motif legendaris ''Batik Sungsang''. Pola geometris dan organis terbalik mencerminkan falsafah keseimbangan kosmos Jawa dan dinamika kehidupan modern. Menggunakan pewarnaan bergradasi halus dengan proses lorotan bertahap yang membutuhkan ketelatenan tinggi, menghasilkan visual estetik yang berwibawa.', '/sungsang.jpg', '["/sungsang.jpg","/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Batik Sungsang dengan motif abstrak dan warna cerah', true, '628816413617', 'Tersedia', '350 gram', 4.9, '["Motif Unik Sungsang Filosofis & Bernilai Seni Tinggi","Pewarnaan Canting Tulis Halus & Bersih","Kain Lembut Jatuh Nyaman Dikenakan","Karya Terbatas Eksklusif Paguyuban Giriloyo"]'::jsonb, '[{"label":"Kategori Produk","value":"Kain Panjang Batik Tulis Halus"},{"label":"Material Kain","value":"Katun Primissima Santung Berkualitas"},{"label":"Dimensi","value":"250 cm x 115 cm"},{"label":"Perawatan","value":"Cuci dengan sabun lerak atau detergen khusus batik"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-7', 'Tatik Batik', 'Kerajinan Tangan', 'Paguyuban Batik Giriloyo', 'Rp950.000', 950000, 'Kain dan tas batik bermotif cantik tersusun rapi dengan sentuhan etnik kontemporer.', 'Kreasi busana dan kain batik tulis paduan warna elegan yang diproduksi oleh pengrajin Tatik Batik di lingkungan Giriloyo. Mengusung warna-warna hangat bumi (earth tone) seperti sogan, terakota, dan indigo alami. Cocok untuk bahan kemeja pria resmi, kebaya modern wanita, maupun kain lilit serbaguna.', '/batik-1.jpg', '["/batik-1.jpg","/batik-2.png","/batik.jpg"]'::jsonb, '', 'Kain dan tas batik bermotif cantik tersusun rapi di rak kayu', true, '628816413617', 'Tersedia', '350 gram', 4.8, '["Warna Alami Earth-Tone Modern Nan Elegan","Serat Kain Rapat & Awet Bertahun-tahun","Bisa Pesan Kembar untuk Seragam Keluarga / Kantor"]'::jsonb, '[{"label":"Material","value":"Katun Mori Primissima Super Halus"},{"label":"Ukuran","value":"240 cm x 110 cm"},{"label":"Pewarna","value":"Pewarna Ramah Lingkungan Tahan Luntur"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-8', 'Kampung Batik Giriloyo', 'Kerajinan Tangan', 'Paguyuban Batik Giriloyo', 'Rp1.200.000', 1200000, 'Karya istimewa perajin batik Giriloyo dengan motif flora khas pedesaan Yogyakarta.', 'Kain batik masterpiece bertema alam pedesaan Wukirsari, menghadirkan untaian sulur daun, burung kepodang, dan ornamen parang seling kembang. Ditulis bolak-balik dengan ketelitian luar biasa oleh ibu-ibu pembatik senior yang telah menggeluti batik selama lebih dari 30 tahun. Simbol keanggunan wanita nusantara dan keagungan budaya Jogja.', '/batik.jpg', '["/batik.jpg","/batik-1.jpg","/sungsang.jpg"]'::jsonb, '', 'Kain batik khas Paguyuban Giriloyo', true, '628816413617', 'Tersedia', '380 gram', 5, '["Karya Masterpiece Pembatik Senior Giriloyo","Motif Flora & Fauna Tradisional Penuh Filosofi","Dua Sisi Tembus Canting Tulis Sempurna","Termasuk Box Kemasan Eksklusif dari Bambu Anyam"]'::jsonb, '[{"label":"Kelas Kualitas","value":"Batik Tulis Halus Koleksi Premium"},{"label":"Kain","value":"Mori Sutra Katun Halus 60s"},{"label":"Ukuran","value":"250 cm x 115 cm"},{"label":"Sertifikasi","value":"Cap Paguyuban Batik Tulis Giriloyo"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-9', 'Wedang Uwuh Rempah', 'Kuliner', 'Wedang Uwuh HJ. Jazimah', 'Rp20.000 / pcs', 20000, 'Racikan komplit rempah alami khas Imogiri, mudah diseduh dan menghangatkan badan.', 'Racikan rempah seduh legendaris dari HJ. Jazimah di kawasan Wukirsari Imogiri. Menggunakan jahe merah organik kering pilihan yang memberikan sensasi pedas mantap dan meredakan letih lelah sehabis seharian beraktivitas. Sangat cocok dinikmati bersama camilan khas desa dan teman bersantai sore hari.', '/uwuh.jpg', '["/uwuh.jpg","https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/831f4e5dfdf72e4880aa6b7ee71b46b8.jpg"]'::jsonb, '', 'Wedang uwuh kemasan siap seduh', true, '628816413617', 'Tersedia', '200 gram', 4.9, '["Jahe Merah Pilihan Pedas Menghangatkan","Kemasan Rapi dan Higienis","Praktis Tinggal Seduh dengan Air Mendidih"]'::jsonb, '[{"label":"Komposisi","value":"Jahe Merah, Secang, Kapulaga, Daun Manis Jangan, Gula Batu"},{"label":"Izin Usaha","value":"P-IRT Terdaftar"},{"label":"Kadaluarsa","value":"1 Tahun"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-10', 'Shalsabila Batik', 'Kerajinan Tangan', 'Shalsabila Batik', 'Rp1.150.000', 1150000, 'Batik sutra dan katun primissima dengan warna tahan lama dan corak anggun.', 'Kain batik Shalsabila menyajikan sentuhan kontemporer untuk generasi muda yang mencintai warisan budaya nusantara. Memadukan corak klasik dengan teknik pewarnaan modern yang segar, cocok untuk acara formal perkantoran, jamuan makan malam, maupun pesta pernikahan adat.', '/batik-2.png', '["/batik-2.png","/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Kain batik Shalsabila', true, '628816413617', 'Tersedia', '350 gram', 4.9, '["Corak Anggun Pas untuk Generasi Muda","Warna Cerah Awet Tidak Memudar","Bahan Adem Nyaman Seharian"]'::jsonb, '[{"label":"Material","value":"Katun Primissima Pilihan"},{"label":"Ukuran","value":"240 cm x 115 cm"},{"label":"Proses","value":"Canting Tulis Kombinasi"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-11', 'Batik Tulis Motif Wahyu Tumurun', 'Kerajinan Tangan', 'Sanggar Sekar Kedhaton Giriloyo', 'Rp1.350.000', 1350000, 'Batik tulis klasik bermakna turunnya anugerah, kemuliaan, dan keberkahan hidup dari Sang Pencipta.', 'Motif Wahyu Tumurun merupakan salah satu mahakarya klasik dari Kampung Batik Giriloyo yang sarat akan doa kemuliaan. Ditulis menggunakan canting tembaga halus di atas kain mori primissima cap kereta kencana dengan pewarna sogan alami kulit kayu tingi dan tegeran. Sangat sakral dikenakan pada upacara pernikahan adat, wisuda, maupun acara kenegaraan.', '/batik.jpg', '["/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Kain batik tulis motif Wahyu Tumurun Giriloyo', true, '628816413617', 'Tersedia', '360 gram', 5, '["Pewarna Alam Sogan Klasik Mataram","Full Tulis Halus Dua Sisi (Bolak-Balik)","Filosofi Kemuliaan & Anugerah Hidup"]'::jsonb, '[{"label":"Motif","value":"Wahyu Tumurun Klasik"},{"label":"Material","value":"Katun Mori Primissima Halus"},{"label":"Ukuran","value":"250 cm x 115 cm"},{"label":"Asal Sentra","value":"Dusun Giriloyo, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-12', 'Batik Tulis Motif Sidomukti Sogan', 'Kerajinan Tangan', 'Paguyuban Batik Giriloyo', 'Rp1.100.000', 1100000, 'Kain batik tulis sogan klasik simbol harapan kemakmuran dan kebahagiaan lahir batin.', 'Batik Tulis Sidomukti dibuat dengan ketekunan tinggi oleh para pembatik ibu-ibu di lereng perbukitan Imogiri. Ornamen kupu-kupu, singgasana, dan kuncup bunga melambangkan cita-cita luhur menuju kemuliaan serta ketenteraman rumah tangga.', '/batik-1.jpg', '["/batik-1.jpg","/batik.jpg"]'::jsonb, '', 'Batik tulis motif Sidomukti Sogan', false, '628816413617', 'Tersedia', '350 gram', 4.9, '["Motif Sakral Adat Jawa","Kain Adem dan Tidak Luntur","Karya Asli Pembatik Perempuan Giriloyo"]'::jsonb, '[{"label":"Motif","value":"Sidomukti Sogan Mataram"},{"label":"Ukuran","value":"245 cm x 115 cm"},{"label":"Lama Pengerjaan","value":"3 Minggu"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-13', 'Batik Tulis Pewarna Alam Indigo', 'Kerajinan Tangan', 'Griya Batik Bimasakti', 'Rp1.250.000', 1250000, 'Batik tulis ramah lingkungan dengan celupan warna biru nila alami daun tom (Indigofera).', 'Menghadirkan nuansa biru laut yang menenangkan dari proses fermentasi daun Indigofera tinctoria yang ditanam di kebun warga Wukirsari. Dicelup berulang kali hingga 15 tahapan untuk menghasilkan gradasi biru indigo yang pekat, ramah kulit sensitif, dan ramah lingkungan.', '/batik-2.png', '["/batik-2.png","/sungsang.jpg"]'::jsonb, '', 'Batik tulis warna alam biru indigo', true, '628816413617', 'Tersedia', '350 gram', 5, '["100% Pasta Indigo Alami Daun Tom","Bebas Bahan Kimia Sintetis","Aroma Alami Khas Rempah & Malam Lebah"]'::jsonb, '[{"label":"Zat Warna","value":"Indigofera Tinctoria & Kulit Kayu Secang"},{"label":"Ukuran","value":"250 cm x 115 cm"},{"label":"Teknik","value":"Canting Tulis & Celup Dingin"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-14', 'Selendang Batik Tulis Sutra', 'Kerajinan Tangan', 'Canting Wukir', 'Rp650.000', 650000, 'Selendang sampur elegan berbahan katun sutra lembut dengan motif lung-lungan bunga.', 'Selendang batik tulis berukuran panjang dengan rumbai halus di kedua ujungnya. Sangat anggun dipadukan dengan kebaya tradisional, busana kerja, maupun dijadikan syal leher saat bepergian ke luar negeri sebagai identitas budaya Indonesia.', '/sungsang.jpg', '["/sungsang.jpg","/batik-2.png"]'::jsonb, '', 'Selendang batik tulis halus', true, '628816413617', 'Tersedia', '200 gram', 4.9, '["Tekstur Sutra Katun Jatuh & Lembut","Cocok untuk Hadiah VIP & Koleksi Pribadi","Kemasan Box Eksklusif"]'::jsonb, '[{"label":"Ukuran Selendang","value":"210 cm x 55 cm"},{"label":"Material","value":"Katun Sutra Primissima"},{"label":"Motif","value":"Lung-lungan Sekar Jagad"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-15', 'Kemeja Pria Batik Tulis Eksklusif', 'Kerajinan Tangan', 'Busana Batik Giriloyo', 'Rp550.000', 550000, 'Kemeja lengan panjang batik tulis siap pakai dengan lapis furing katun adem.', 'Kemeja pria berpotongan regular-fit yang dijahit rapi oleh penjahit tailormade lokal Wukirsari dengan penempatan motif (pola sanggit) yang presisi di bagian dada dan saku. Dilengkapi furing katun dormeuil yang menyerap keringat sehingga nyaman dipakai seharian.', '/batik.jpg', '["/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Kemeja batik tulis pria eksklusif', false, '628816413617', 'Tersedia', '400 gram', 4.8, '["Jahitan Tailor Rapi dengan Pola Sanggit Presisi","Dilapisi Furing Katun Adem","Tersedia Ukuran M, L, XL, XXL"]'::jsonb, '[{"label":"Bahan","value":"Batik Tulis Kombinasi & Furing Katun"},{"label":"Model","value":"Lengan Panjang Kerah Tegak"},{"label":"Pilihan Ukuran","value":"M, L, XL, XXL"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-16', 'Outer Wanita Batik Kombinasi Lurik', 'Kerajinan Tangan', 'Shalsabila Batik', 'Rp380.000', 380000, 'Luaran (cardigan/outer) wanita modis perpaduan batik tulis Giriloyo dan tenun lurik tradisional.', 'Busana kasual semi-formal yang memadukan keindahan motif batik tulis Wukirsari dengan garis tegas kain tenun lurik Yogyakarta. Desain modern all-size yang serasi dipadukan dengan kemeja polos, celana kulot, maupun rok lilit.', '/batik-2.png', '["/batik-2.png","/batik-1.jpg"]'::jsonb, '', 'Outer wanita batik kombinasi lurik', true, '628816413617', 'Tersedia', '300 gram', 4.9, '["Desain Kontemporer Cocok untuk Ngantor & Hangout","Perpaduan Unik Batik Giriloyo & Lurik ATBM","Nyaman dan Tidak Gerah"]'::jsonb, '[{"label":"Material","value":"Katun Batik & Tenun Lurik Benang Katun"},{"label":"Ukuran","value":"All Size Fit to XL (LD 110 cm)"},{"label":"Panjang Baju","value":"75 cm"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-17', 'Tas Totebag Perca Batik Kanvas', 'Kerajinan Tangan', 'Kriya Perca Wukirsari', 'Rp85.000', 85000, 'Tas bahu totebag kuat dari perpaduan kanvas tebal dan patchwork kain perca batik tulis.', 'Produk upcycling ramah lingkungan karya kelompok ibu rumah tangga Desa Wukirsari. Mengolah sisa potongan kain batik tulis berkualitas menjadi tas totebag berdesain patchwork unik yang dilengkapi resleting utama dan kantong dalam untuk laptop 14 inci.', '/batik-1.jpg', '["/batik-1.jpg","/kipas.jpg"]'::jsonb, '', 'Tas totebag batik perca', true, '628816413617', 'Tersedia', '250 gram', 4.8, '["Muat Laptop 14 Inci & Buku Kuliah","Dilengkapi Resleting & Furing Dalam Tahan Air","Setiap Tas Memiliki Motif Perca Berbeda"]'::jsonb, '[{"label":"Dimensi","value":"38 cm x 32 cm x 10 cm"},{"label":"Bahan","value":"Kanvas Marsoto & Perca Batik Tulis"},{"label":"Penutup","value":"Resleting YKK Kuat"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-18', 'Dompet Pouch Kosmetik Batik', 'Kerajinan Tangan', 'Kriya Perca Wukirsari', 'Rp35.000', 35000, 'Dompet serbaguna berlapis busa empuk dengan motif batik klasik dan tali pegangan.', 'Pouch serbaguna untuk menyimpan kosmetik, gawai, uang tunai, maupun perlengkapan ibadah. Dijahit rapi dengan lapisan busa pelindung di bagian dalam sehingga aman dari benturan ringan. Sangat populer dipesan sebagai suvenir pernikahan dan seminar.', '/kipas.jpg', '["/kipas.jpg","/batik-1.jpg"]'::jsonb, '', 'Dompet pouch batik Wukirsari', false, '628816413617', 'Tersedia', '90 gram', 4.7, '["Dilapisi Busa Pelindung Empuk","Bisa Custom Sablon/Label Acara","Harga Hemat untuk Souvenir Massal"]'::jsonb, '[{"label":"Ukuran","value":"22 cm x 14 cm x 5 cm"},{"label":"Bahan","value":"Katun Batik & Lapisan Satin"},{"label":"Minimal Order Custom","value":"50 pcs (Satuan Tetap Dilayani)"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-19', 'Blangkon Jogja Lipat Motif Modang', 'Kerajinan Tangan', 'Kriya Busana Mataram', 'Rp125.000', 125000, 'Penutup kepala adat gaya Yogyakarta dengan mondolan belakang dan motif batik Modang.', 'Blangkon gaya Ngayogyakarta Hadiningrat yang dikerjakan dengan teknik plipit dan jahit tangan tanpa lem kimia berlebih, sehingga bisa dilipat, dicuci, dan nyaman mengikuti bentuk lingkar kepala.', '/batik.jpg', '["/batik.jpg","/sungsang.jpg"]'::jsonb, '', 'Blangkon Jogja motif Modang', true, '628816413617', 'Tersedia', '180 gram', 4.9, '["Kualitas Halus Bisa Dilipat & Dicuci","Gaya Khas Mataram Yogyakarta (Mondolan)","Tersedia Ukuran Lingkar Kepala 55 - 60"]'::jsonb, '[{"label":"Gaya","value":"Mataram Ngayogyakarta"},{"label":"Motif","value":"Modang / Kumitir / Jebehan"},{"label":"Ukuran","value":"No. 5, 6, 7, 8, 9, 10"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-20', 'Taplak Meja Tamu Batik Cap Kombinasi', 'Kerajinan Tangan', 'Tatik Batik', 'Rp145.000', 145000, 'Taplak meja ruang tamu estetik bermotif ceplok sekar dengan rumbai benang katun.', 'Mempercantik interior ruang tamu atau ruang makan Anda dengan sentuhan budaya Jawa. Dibuat dari katun tebal tidak licin di atas meja kayu maupun kaca, dengan pewarnaan yang tahan cuci.', '/batik-1.jpg', '["/batik-1.jpg","/batik.jpg"]'::jsonb, '', 'Taplak meja batik tradisional', false, '628816413617', 'Tersedia', '250 gram', 4.8, '["Kain Katun Tebal Tidak Mudah Geser","Motif Etnik Memperindah Ruang Tamu","Mudah Dicuci & Cepat Kering"]'::jsonb, '[{"label":"Ukuran","value":"110 cm x 110 cm (Persegi)"},{"label":"Material","value":"Katun Prima Tebal"},{"label":"Teknik","value":"Batik Cap Kombinasi Colet"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-21', 'Syal Ecoprint Daun Jati & Lanang', 'Kerajinan Tangan', 'Ecoprint Alam Wukir', 'Rp220.000', 220000, 'Syal kain katun rayon dengan cetakan pigmen asli dedaunan hutan perbukitan Wukirsari.', 'Diproduksi dengan teknik kukus (steaming) dedaunan segar seperti daun jati muda, daun lanang, daun jambu, dan bunga kenikir yang tumbuh subur di Wukirsari. Setiap helai syal adalah karya tunggal (one of a kind) karena jejak tulang daun tidak pernah bisa sama persis.', '/sungsang.jpg', '["/sungsang.jpg","/batik-2.png"]'::jsonb, '', 'Syal ecoprint daun alami Wukirsari', true, '628816413617', 'Tersedia', '190 gram', 4.9, '["100% Jejak Pigmen Daun Asli Tanpa Tinta Cetak","Desain Tunggal Eksklusif (One of a Kind)","Serat Kain Sejuk di Kulit"]'::jsonb, '[{"label":"Teknik","value":"Ecoprint Steam Blanket"},{"label":"Bahan","value":"Katun Rayon Viscose Premium"},{"label":"Ukuran","value":"180 cm x 60 cm"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-22', 'Kipas Bambu Jumbo Lukis Tangan', 'Kerajinan Tangan', 'Zainal Kipas Karangtalun', 'Rp175.000', 175000, 'Kipas dinding dekoratif ukuran besar dari bambu wulung dan kain lukis pemandangan desa.', 'Kipas bambu ukuran jumbo yang dirancang khusus sebagai hiasan dinding ruang keluarga, lobi hotel, restoran bernuansa Jawa, maupun latar pelaminan. Rangka dibuat dari bambu wulung tua yang diawetkan secara alami agar bebas bubuk kayu.', '/kipas.jpg', '["/kipas.jpg","/sawah.jpg"]'::jsonb, '', 'Kipas bambu jumbo dekorasi dinding', true, '628816413617', 'Tersedia', '650 gram', 4.9, '["Lebar Bentangan Mencapai 100 cm","Rangka Bambu Wulung Awet & Kokoh","Dilengkapi Pengait Gantungan Dinding"]'::jsonb, '[{"label":"Diameter Bentang","value":"100 cm x 55 cm"},{"label":"Rangka","value":"Bambu Wulung Pilihan"},{"label":"Asal Sentra","value":"Dusun Karangtalun, Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-23', 'Paket Souvenir Kipas Batik (Isi 50 Pcs)', 'Kerajinan Tangan', 'Zainal Kipas Karangtalun', 'Rp850.000 / 50 pcs', 850000, 'Paket hemat 50 kipas bambu batik lengkap dengan kemasan tile/box dan kartu ucapan terima kasih.', 'Solusi praktis untuk calon pengantin, panitia wisuda, maupun instansi pemerintah yang membutuhkan cenderamata otentik khas Desa Wisata Wukirsari. Setiap kipas sudah dikemas rapi dengan pita rami dan kartu nama acara sesuai pesanan.', '/kipas.jpg', '["/kipas.jpg","/batik-1.jpg"]'::jsonb, '', 'Paket souvenir kipas bambu batik', false, '628816413617', 'Tersedia', '3500 gram', 5, '["Sudah Termasuk Kemasan & Kartu Nama Custom","Harga Grosir Langsung dari Pengrajin","Motif Batik Campur Serasi"]'::jsonb, '[{"label":"Isi Paket","value":"50 Pcs Kipas Bambu Batik"},{"label":"Bonus","value":"Kemasan Plastik/Tile + Kartu Ucapan"},{"label":"Waktu Pengerjaan","value":"5 - 7 Hari Kerja"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-24', 'Besek Bambu Anyaman Halus Sepasang', 'Kerajinan Tangan', 'Anyaman Bambu Nogosari', 'Rp12.000 / pasang', 12000, 'Wadah besek bambu ramah lingkungan pengganti kotak plastik untuk hantaran kuliner dan hampers.', 'Dianyam secara telaten oleh para perajin bambu di perbukitan Wukirsari menggunakan bilah bambu apus yang diserut tipis, dikeringkan di bawah sinar matahari, dan diputihkan secara alami tanpa pemutih berbahaya. Aman untuk wadah makanan langsung seperti gudeg, thiwul, maupun daging kurban.', '/kipas.jpg', '["/kipas.jpg","/uwuh.jpg"]'::jsonb, '', 'Besek bambu anyaman halus', false, '628816413617', 'Tersedia', '120 gram', 4.8, '["Food Grade Aman Tanpa Pemutih Kimia","Anyaman Rapat, Bersih, Tidak Berserabut","100% Biodegradable Ramah Lingkungan"]'::jsonb, '[{"label":"Ukuran","value":"20 cm x 20 cm x 10 cm"},{"label":"Bahan","value":"Bambu Apus Kering Alami"},{"label":"Isi","value":"1 Pasang (Wadah + Tutup)"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-25', 'Kap Lampu Gantung Anyaman Bambu', 'Kerajinan Tangan', 'Anyaman Bambu Nogosari', 'Rp165.000', 165000, 'Tudung lampu gantung estetik dari anyaman bambu yang memancarkan bayangan cahaya hangat.', 'Kap lampu bergaya tropis-pedesaan (rustic) yang dianyam dengan pola mata walik dan kurung. Ketika lampu dinyalakan di malam hari, celah anyaman bambu membiaskan pola cahaya dramatis yang menenangkan di teras rumah, gazebo, maupun kafe.', '/kipas.jpg', '["/kipas.jpg","/sawah.jpg"]'::jsonb, '', 'Kap lampu anyaman bambu Wukirsari', true, '628816413617', 'Tersedia', '450 gram', 4.9, '["Finishing Pernis Clear Tahan Lembab & Jamur","Desain Estetik untuk Teras, Kafe & Homestay","Ringan dan Mudah Dipasang pada Fitting Standar"]'::jsonb, '[{"label":"Diameter","value":"35 cm, Tinggi 40 cm"},{"label":"Material","value":"Bambu Apus & Rotan Ikat"},{"label":"Kelengkapan","value":"Kap Bambu + Dudukan Fitting E27"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-26', 'Set Alat Membatik Pemula (Canting & Malam)', 'Kerajinan Tangan', 'Paguyuban Batik Giriloyo', 'Rp95.000', 95000, 'Paket lengkap belajar membatik mandiri di rumah berisi canting, malam, dan kain pola.', 'Ingin merasakan serunya mencanting batik tulis seperti di Kampung Batik Giriloyo dari rumah? Paket edukasi ini dilengkapi canting tembaga klowong, lilin malam kualitas super, kain mori yang sudah digambari pola motif klasik, serta panduan langkah demi langkah.', '/batik.jpg', '["/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Set alat membatik pemula', true, '628816413617', 'Tersedia', '350 gram', 4.9, '["Cocok untuk Tugas Sekolah, Hobi & Edukasi Anak","Sudah Termasuk Kain Mori Berpola Siap Canting","Canting Tembaga Asli Buatan Pengrajin"]'::jsonb, '[{"label":"Isi Paket","value":"2 Canting, 200gr Malam, 2 Kain Mori Pola 40x40cm, Panduan"},{"label":"Tingkat Kesulitan","value":"Pemula / Anak-anak & Dewasa"},{"label":"Asal Produk","value":"Kampung Batik Giriloyo"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-27', 'Wayang Kulit Gunungan Kayon Prada Emas', 'Seni Pertunjukan', 'Ituk Wayang Pucung', 'Rp850.000', 850000, 'Wayang kulit Kayon (Gunungan) lambang jagad raya dengan tatah sungging rumit dan prada emas.', 'Gunungan atau Kayon adalah simbol pohon kehidupan (Kalpataru) dan makrokosmos alam semesta dalam dunia pewayangan Jawa. Dipahat dari kulit kerbau pilihan oleh empu tatah sungging Dusun Pucung, dengan detail pohon hayat, gerbang istana, raksasa penjaga Cingkarabala-Balaupata, serta satwa hutan.', '/wayang.jpeg', '["/wayang.jpeg","/batik.jpg"]'::jsonb, '', 'Wayang kulit Gunungan Kayon Pucung', true, '628816413617', 'Tersedia', '550 gram', 5, '["Simbol Pohon Kehidupan & Semesta Jawa","Tatahan Sangat Rapat & Halus Standar Pedalangan","Gapit Tanduk Kerbau Bule Pilihan"]'::jsonb, '[{"label":"Tinggi Total","value":"75 cm (Termasuk Gapit Tanduk)"},{"label":"Material","value":"Kulit Kerbau & Tanduk Kerbau Asli"},{"label":"Asal Sentra","value":"Dusun Pucung, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-28', 'Wayang Kulit Tokoh Semar Badranaya', 'Seni Pertunjukan', 'Sanggar Tatah Sungging Pucung', 'Rp650.000', 650000, 'Wayang kulit pamomong agung Kyai Lurah Semar simbol kebijaksanaan, kerendahan hati, dan pengayom.', 'Tokoh Semar dalam khazanah budaya Jawa dipandang sebagai pamomong para ksatria yang sarat wejangan hidup. Dikerjakan dengan teknik sungging gradasi klasik dan sapuan prada emas di bagian kain kampuh poleng.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Wayang kulit tokoh Semar', false, '628816413617', 'Tersedia', '420 gram', 4.9, '["Tokoh Falsafah Jawa Paling Digemari Kolektor","Kulit Kerbau Tebal Tidak Melengkung","Dilengkapi Dudukan Kayu Jati untuk Pajangan Meja"]'::jsonb, '[{"label":"Tokoh","value":"Kyai Lurah Semar Badranaya"},{"label":"Ukuran","value":"Standar Pedalangan (Tinggi 55 cm)"},{"label":"Bonus","value":"Stand Dudukan Kayu Jati Ukir"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-29', 'Wayang Kulit Werkudara (Bima)', 'Seni Pertunjukan', 'Ituk Wayang Pucung', 'Rp750.000', 750000, 'Wayang kulit ksatria Jodhipati Raden Werkudara simbol keteguhan prinsip, kejujuran, dan kekuatan.', 'Menampilkan gagahnya tokoh Bima atau Werkudara dengan kuku Pancanaka dan kain poleng bangbintulu. Ukuran wayang lebih tinggi dan besar dibandingkan tokoh ksatria biasa, dipahat dari lembaran kulit kerbau bagian punggung yang kokoh.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Wayang kulit tokoh Werkudara Bima', true, '628816413617', 'Tersedia', '600 gram', 4.9, '["Postur Gagah Ukuran Jangkung Pedalangan","Detail Sungging Poleng Bangbintulu Presisi","Karya Empu Wayang Dusun Pucung"]'::jsonb, '[{"label":"Tokoh","value":"Raden Werkudara / Bratasena"},{"label":"Tinggi","value":"80 cm (dengan Gapit Tanduk)"},{"label":"Material","value":"100% Kulit Kerbau Pilihan"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-30', 'Wayang Kulit Sri Rama & Dewi Shinta (Sepasang)', 'Seni Pertunjukan', 'Sanggar Tatah Sungging Pucung', 'Rp1.150.000 / pasang', 1150000, 'Sepasang wayang kulit Rama dan Shinta lambang kesetiaan cinta sejati, cocok untuk kado pernikahan.', 'Hadirkan simbol keharmonisan dan kesetiaan abadi kisah Ramayana melalui sepasang wayang kulit Sri Rama Wijaya dan Dewi Shinta. Sangat populer dijadikan kado pernikahan eksklusif, cenderamata ulang tahun pernikahan, maupun dekorasi ruang utama.', '/wayang.jpeg', '["/wayang.jpeg","/batik-1.jpg"]'::jsonb, '', 'Sepasang wayang kulit Rama dan Shinta', true, '628816413617', 'Tersedia', '750 gram', 5, '["Paket Sepasang (2 Buah Wayang Kulit)","Hadiah Pernikahan & Anniversary Paling Berkesan","Termasuk 2 Dudukan Kayu Jati"]'::jsonb, '[{"label":"Isi Paket","value":"1 Wayang Rama + 1 Wayang Shinta + 2 Dudukan Kayu"},{"label":"Tinggi","value":"60 cm"},{"label":"Material","value":"Kulit Kerbau & Gapit Tanduk"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-31', 'Wayang Kulit Punakawan Lengkap (4 Tokoh)', 'Seni Pertunjukan', 'Ituk Wayang Pucung', 'Rp1.950.000 / set', 1950000, 'Satu set lengkap empat tokoh Punakawan: Semar, Gareng, Petruk, dan Bagong kualitas pedalangan.', 'Koleksi lengkap keluarga Punakawan yang selalu menghadirkan humor cerdas, kritik sosial santun, dan petuah luhur dalam pagelaran wayang. Keempat tokoh dibuat serasi dengan standar tatah sungging halus Dusun Pucung.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Set wayang kulit Punakawan 4 tokoh', false, '628816413617', 'Tersedia', '1600 gram', 5, '["Lengkap 4 Tokoh (Semar, Gareng, Petruk, Bagong)","Kualitas Pentas Dalang & Koleksi Museum","Harga Lebih Hemat Dibanding Beli Satuan"]'::jsonb, '[{"label":"Jumlah","value":"4 Tokoh Wayang Kulit Ukuran Standar"},{"label":"Bahan","value":"Kulit Kerbau Super & Gapit Tanduk"},{"label":"Asal Sentra","value":"Pucung, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-32', 'Lukisan Wayang Kulit Berbingkai Jati Ukir', 'Seni Pertunjukan', 'Galeri Kriya Pucung', 'Rp520.000', 520000, 'Hiasan dinding wayang kulit asli dalam bingkai kaca kayu jati berukir beludru hitam.', 'Wayang kulit tatah sungging yang dibentangkan rapi di atas kain beludru hitam pekat dan dibingkai dengan kayu jati ukir berpelindung kaca. Melindungi wayang dari debu dan menjadikannya dekorasi dinding yang mewah untuk ruang tamu maupun ruang kerja.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Bingkai wayang kulit kayu jati', true, '628816413617', 'Tersedia', '2200 gram', 4.8, '["Bebas Debu dengan Bingkai Kaca & Kayu Jati","Latar Beludru Hitam Menonjolkan Warna Prada Emas","Bisa Pilih Tokoh Wayang Sesuai Keinginan"]'::jsonb, '[{"label":"Dimensi Bingkai","value":"65 cm x 45 cm x 5 cm"},{"label":"Bahan Bingkai","value":"Kayu Jati Finishing Melamin"},{"label":"Packing","value":"Termasuk Packing Kayu Aman"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-33', 'Kap Lampu Meja Kulit Kerbau Ukir', 'Seni Pertunjukan', 'Galeri Kriya Pucung', 'Rp275.000', 275000, 'Lampu tidur meja dari kulit kerbau transparan dengan ukiran tatah sungging motif pohon hayat.', 'Inovasi produk kriya dari pengrajin wayang Dusun Pucung. Memanfaatkan sifat tembus cahaya dari kulit kerbau tipis yang ditatah dengan ornamen klasik. Saat lampu dinyalakan, warna-warni sunggingan memancarkan pendar hangat yang eksotis.', '/wayang.jpeg', '["/wayang.jpeg","/kipas.jpg"]'::jsonb, '', 'Lampu meja kulit ukir Pucung', true, '628816413617', 'Tersedia', '600 gram', 4.9, '["Cahaya Tembus Kulit Kerbau Tatah Sungging","Sudah Termasuk Bohlam LED Warm White & Kabel Saklar","Dudukan Kayu Mahoni Kokoh"]'::jsonb, '[{"label":"Tinggi Lampu","value":"38 cm, Diameter 18 cm"},{"label":"Daya","value":"LED 5 Watt (Hemat Listrik)"},{"label":"Material","value":"Kulit Kerbau Asli & Kayu Mahoni"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-34', 'Souvenir Gantungan Kunci & Pembatas Buku Wayang', 'Seni Pertunjukan', 'Kriya Muda Pucung', 'Rp50.000 / paket 5 pcs', 50000, 'Paket 5 buah pembatas buku dan gantungan kunci miniatur wayang dari kulit asli.', 'Cenderamata ringan dan bernilai seni tinggi yang dibuat dari potongan kulit kerbau asli dengan tatah dan sungging manual (bukan cetakan mesin). Sangat digemari wisatawan mancanegara, pelajar, dan pecinta literasi.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Souvenir pembatas buku wayang kulit', false, '628816413617', 'Tersedia', '100 gram', 4.8, '["100% Kulit Asli Ditatah & Diwarnai Manual","Ringan dan Awet Tidak Mudah Sobek","Berisi 5 Karakter Wayang Berbeda"]'::jsonb, '[{"label":"Isi Paket","value":"3 Pembatas Buku + 2 Gantungan Kunci Kulit"},{"label":"Ukuran","value":"Tinggi 12 - 15 cm"},{"label":"Kemasan","value":"Plastik Opp & Kertas Penjelasan Tokoh"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-35', 'Topeng Kayu Klasik Panji Asmarabangun', 'Seni Pertunjukan', 'Sanggar Seni Karaton Wukir', 'Rp185.000', 185000, 'Topeng kayu pule ukir halus dengan motif batik tulis untuk tari tradisional maupun pajangan.', 'Dipahat dari kayu pule pilihan yang ringan namun ulet, kemudian dihaluskan dan dilukis dengan motif batik klasik menggunakan kuas halus. Menampilkan karakter lembut Raden Panji yang meneduhkan.', '/wayang.jpeg', '["/wayang.jpeg","/batik.jpg"]'::jsonb, '', 'Topeng kayu batik tradisional', true, '628816413617', 'Tersedia', '280 gram', 4.8, '["Kayu Pule Ringan Standar Penari Tradisional","Motif Lukis Batik Halus","Dilengkapi Pengait Gantungan Dinding"]'::jsonb, '[{"label":"Ukuran","value":"20 cm x 16 cm"},{"label":"Material","value":"Kayu Pule Kering"},{"label":"Finishing","value":"Cat Akrilik & Coating Glossy"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-36', 'Paket Pentas Karawitan & Wayang Kulit', 'Seni Pertunjukan', 'Paguyuban Seni Wukir Budaya', 'Rp3.500.000 / sesi', 3500000, 'Layanan pementasan musik gamelan karawitan dan wayang kulit durasi singkat untuk penyambutan tamu.', 'Hadirkan kemegahan seni pertunjukan asli Desa Wisata Wukirsari untuk acara penyambutan tamu kehormatan, gala dinner, pernikahan, maupun kunjungan instansi. Melibatkan pengrawit senior, pesinden, dan dalang muda berbakat dari Wukirsari.', '/wayang.jpeg', '["/wayang.jpeg","/sawah.jpg"]'::jsonb, '', 'Pertunjukan wayang kulit dan karawitan Wukirsari', true, '628816413617', 'Tersedia', '1000 gram', 5, '["Seniman Pengrawit, Sinden & Dalang Asli Desa Wukirsari","Durasi Fleksibel (Lakon Padat 1-2 Jam)","Bisa Dipentaskan di Pendopo Desa atau Lokasi Acara"]'::jsonb, '[{"label":"Personel","value":"10 Pengrawit + 2 Sinden + 1 Dalang"},{"label":"Durasi","value":"2 Jam Pertunjukan"},{"label":"Cakupan","value":"Area Desa Wukirsari & D.I. Yogyakarta"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-37', 'Wedang Uwuh Celup Praktis (Box 15 Kantong)', 'Kuliner', 'UMKM Rempah Imogiri', 'Rp30.000 / box', 30000, 'Inovasi wedang uwuh dalam kantong teh celup tanpa ampas, praktis diseduh kapan saja di kantor.', 'Menjawab kebutuhan gaya hidup modern tanpa mengurangi khasiat rempah asli Imogiri. Seluruh bahan jahe merah, kayu secang, cengkeh, pala, dan kayu manis digiling kasar dan dikemas dalam kantong teh celup food-grade bebas klorin.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Wedang uwuh celup praktis', true, '628816413617', 'Tersedia', '150 gram', 4.9, '["Praktis Tanpa Ampas Rempah di Gelas","Tetap Merah Alami dari Ekstrak Kayu Secang","Cocok untuk Bekal Perjalanan & Kantor"]'::jsonb, '[{"label":"Isi Box","value":"15 Kantong Celup @ 5 gram"},{"label":"Komposisi","value":"100% Rempah Murni Tanpa Perisa Sintetis"},{"label":"Masa Simpan","value":"18 Bulan"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-38', 'Sirup Wedang Uwuh Botol Kaca (500 ml)', 'Kuliner', 'Wedang Uwuh Bu Endang', 'Rp45.000 / botol', 45000, 'Ekstrak konsentrat wedang uwuh kental manis alami, nikmat disajikan hangat maupun es dingin.', 'Sirup rempah kental yang dimasak perlahan menggunakan kuali tanah liat dari perpaduan sari jahe emprit, secang, cengkeh, serai, dan gula batu murni. Cukup tuangkan 3 sendok makan ke dalam segelas air hangat atau tambahkan es batu dan potongan jeruk nipis untuk minuman segar.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Sirup wedang uwuh botol', true, '628816413617', 'Tersedia', '750 gram', 4.9, '["Bisa Disajikan Hangat maupun Es Segar","1 Botol untuk 15 - 18 Gelas Sajian","Tanpa Pemanis Buatan"]'::jsonb, '[{"label":"Volume Bersih","value":"500 ml"},{"label":"Kemasan","value":"Botol Kaca Segel + Bubble Wrap Tebal"},{"label":"Ketahanan","value":"6 Bulan (Simpan di Kulkas Setelah Dibuka)"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-39', 'Wedang Uwuh Instan Bubuk Gula Aren (Isi 10 Sachet)', 'Kuliner', 'Wedang Uwuh HJ. Jazimah', 'Rp28.000 / pouch', 28000, 'Minuman bubuk wedang uwuh larut sempurna dengan manis legit gula aren organik.', 'Diproses melalui kristalisasi sari rempah wedang uwuh bersama nira gula aren murni. Cukup sobek sachet, seduh dengan air panas, aduk sebentar, dan langsung siap diminum tanpa perlu menyaring dedaunan.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Wedang uwuh bubuk gula aren', false, '628816413617', 'Tersedia', '250 gram', 4.8, '["Manis Alami Gula Aren Indeks Glikemik Rendah","100% Larut Tanpa Ampas","Pouch Ziplock Kedap Udara"]'::jsonb, '[{"label":"Isi Kemasan","value":"10 Sachet @ 22 gram"},{"label":"Pemanis","value":"Gula Aren Murni"},{"label":"Sertifikasi","value":"Halal & P-IRT"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-40', 'Pecel Kembang Turi & Sayur Segar Imogiri', 'Kuliner', 'Dapur Bu Parmi Imogiri', 'Rp15.000 / porsi', 15000, 'Hidangan pecel legendaris khas Imogiri dengan rebusan kembang turi putih, bayam, dan sambal kacang kencur.', 'Kuliner pagi dan siang favorit para peziarah Makam Raja-Raja Imogiri. Menggunakan kembang turi segar yang dipetik pagi hari dari pekarangan desa, dipadukan dengan kecambah, kacang panjang, daun kenikir, dan siraman sambal kacang tanah sangrai beraroma kencur dan daun jeruk purut.', '/images/destinasi/pecel-imogiri.jpg', '["/images/destinasi/pecel-imogiri.jpg","/uwuh.jpg"]'::jsonb, '', 'Pecel kembang turi khas Imogiri', true, '628816413617', 'Tersedia', '300 gram', 4.9, '["Kembang Turi Segar Kaya Serat & Vitamin","Bumbu Kacang Sangrai Tanpa Minyak Goreng","Disajikan di Atas Pincuk Daun Jati / Pisang"]'::jsonb, '[{"label":"Isi Sajian","value":"Sayuran Rebus, Kembang Turi, Bumbu Pecel, Peyek Kacang"},{"label":"Opsi Pesanan","value":"Siap Santap di Lokasi / Bumbu Pecel Kemasan Oleh-Oleh"},{"label":"Asal Kuliner","value":"Kawasan Pajimatan Imogiri, Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-41', 'Geplak Bantul Kelapa Muda (Kotak 500 gr)', 'Kuliner', 'Geplak Sari Rasa Wukirsari', 'Rp25.000 / kotak', 25000, 'Kudapan manis gurih warna-warni dari parutan kelapa muda pilihan dan tepung beras sangrai.', 'Oleh-oleh klasik khas Kabupaten Bantul yang dibuat segar setiap hari di Wukirsari. Teksturnya empuk di dalam dan sedikit renyah di luar, dengan aroma pandan, jahe, dan vanili alami.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg"]'::jsonb, '', 'Geplak kelapa muda khas Bantul', false, '628816413617', 'Tersedia', '500 gram', 4.8, '["Kelapa Muda Segar Tidak Tengik","Dikemas dalam Besek Bambu Tradisional","Oleh-Oleh Ikonik Bantul Yogyakarta"]'::jsonb, '[{"label":"Berat Bersih","value":"500 gram"},{"label":"Bahan","value":"Kelapa Parut, Gula Pasir, Gula Jawa, Tepung Ketan"},{"label":"Daya Tahan","value":"10 Hari Suhu Ruang"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-42', 'Peyek Tumpuk Mbok Tumpuk (Kemasan 400 gr)', 'Kuliner', 'Sentra Kuliner Peyek Imogiri', 'Rp32.000 / bungkus', 32000, 'Rempeyek kacang tanah bertumpuk tebal namun super renyah dan gurih khas Imogiri.', 'Berbeda dari rempeyek tipis biasa, Peyek Tumpuk khas Imogiri digoreng dengan teknik khusus menggunakan kayu bakar hingga membentuk bongkahan berongga yang bertumpuk-tumpuk. Meski tebal, teksturnya sangat renyah, tidak keras, dan kaya taburan kacang tanah lokal.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Peyek tumpuk khas Imogiri', true, '628816413617', 'Tersedia', '400 gram', 4.9, '["Renyah Empuk Meski Berbentuk Tebal Bertumpuk","Dimasak Tradisional dengan Tungku Kayu Bakar","Kacang Tanah Melimpah & Bumbu Kencur Daun Jeruk"]'::jsonb, '[{"label":"Berat","value":"400 gram"},{"label":"Komposisi","value":"Tepung Beras, Kacang Tanah, Santan, Kemiri, Kencur"},{"label":"Ketahanan","value":"1 Bulan dalam Toples Rapat"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-43', 'Keripik Tempe Sagu Renyah (250 gr)', 'Kuliner', 'Kube Mekar Jaya Wukirsari', 'Rp18.000 / pouch', 18000, 'Irisan tipis tempe kedelai peragian sagu yang digoreng garing dengan bumbu bawang ketumbar.', 'Camilan sehat kaya protein nabati yang diolah oleh kelompok usaha bersama (Kube) ibu-ibu Dusun Karangasem, Wukirsari. Diiris setipis kertas dan ditiriskan dengan mesin spinner sehingga minim minyak dan tahan lama kerenyahannya.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Keripik tempe sagu renyah', false, '628816413617', 'Tersedia', '250 gram', 4.8, '["Ditiriskan dengan Spinner (Tidak Berminyak)","Kedelai Lokal Pilihan & Tanpa MSG Berlebih","Kemasan Standing Pouch Ziplock"]'::jsonb, '[{"label":"Berat Bersih","value":"250 gram"},{"label":"Varian Rasa","value":"Original Bawang / Pedas Daun Jeruk"},{"label":"Masa Simpan","value":"3 Bulan"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-44', 'Gatot Singkong Instan Kering (400 gr)', 'Kuliner', 'Mbak Iswati', 'Rp18.000 / pack', 18000, 'Olahan gaplek singkong hitam kenyal khas perbukitan selatan, praktis tinggal rendam dan kukus.', 'Sahabat sejati Thiwul! Gatot dibuat dari singkong pilihan yang difermentasi alami di bawah embun dan sinar matahari hingga berwarna gelap dan bertekstur kenyal seperti jeli. Kaya akan probiotik alami yang sangat baik untuk pencernaan.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg"]'::jsonb, '', 'Gatot singkong tradisional', true, '628816413617', 'Tersedia', '400 gram', 4.8, '["Tekstur Kenyal Legit Khas Gunungkidul & Imogiri","Kaya Serat Pangan & Bebas Gluten","Tahan Simpan 6 Bulan dalam Keadaan Kering"]'::jsonb, '[{"label":"Berat Bersih","value":"400 gram (Menjadi 4-5 Porsi Matang)"},{"label":"Cara Masak","value":"Rendam Air Hangat 30 Menit Lalu Kukus 20 Menit"},{"label":"Asal Produk","value":"Desa Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-45', 'Madu Hutan Klanceng Trigona Asli (250 ml)', 'Kuliner', 'Kelompok Tani Hutan Wukirsari', 'Rp85.000 / botol', 85000, 'Madu murni lebah tanpa sengat (Trigona/Klanceng) dengan cita rasa manis asam segar kaya propolis.', 'Dipanen secara lestari dari stup koloni lebah klanceng yang menghisap nektar bunga kaliandra, bunga mangga, dan tanaman herbal di perbukitan Wukirsari. Kandungan propolis dan bee pollen alaminya jauh lebih tinggi dibanding madu biasa, efektif menjaga daya tahan tubuh.', '/uwuh.jpg', '["/uwuh.jpg","/sawah.jpg"]'::jsonb, '', 'Madu klanceng asli perbukitan Wukirsari', true, '628816413617', 'Tersedia', '400 gram', 5, '["100% Madu Mentah (Raw Honey) Tanpa Pemanasan","Kaya Propolis, Bee Pollen & Antioksidan Tinggi","Hasil Panen Kelompok Tani Hutan Wukirsari"]'::jsonb, '[{"label":"Volume","value":"250 ml"},{"label":"Jenis Lebah","value":"Trigona sp. (Lebah Klanceng Tanpa Sengat)"},{"label":"Rasa Khas","value":"Manis Segar Sedikit Asam Alami"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-46', 'Gula Semut Kelapa Organik (500 gr)', 'Kuliner', 'Sari Nira Wukirsari', 'Rp24.000 / pouch', 24000, 'Gula kelapa kristal bubuk murni dari sadapan nira pohon kelapa perbukitan Wukirsari.', 'Pemanis sehat alami pengganti gula pasir rafinasi. Diolah oleh penderes nira lokal tanpa campuran pengawet sulfit, menghasilkan butiran gula semut kering beraroma karamel lembut yang cocok untuk seduhan kopi, teh, wedang jahe, maupun pembuatan kue.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Gula semut kelapa organik', false, '628816413617', 'Tersedia', '500 gram', 4.9, '["100% Nira Kelapa Murni Tanpa Campuran Gula Pasir","Indeks Glikemik Lebih Rendah","Mudah Larut & Tidak Menggumpal"]'::jsonb, '[{"label":"Berat Bersih","value":"500 gram"},{"label":"Kadar Air","value":"< 2% (Sangat Kering & Awet)"},{"label":"Masa Simpan","value":"12 Bulan"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-47', 'Jamu Kunyit Asam & Beras Kencur Segar (Paket 2 Botol)', 'Kuliner', 'Jamu Gendong Mbakarni', 'Rp25.000 / 2 botol', 25000, 'Minuman jamu tradisional segar racikan rimpang kunyit, kencur, asam jawa, dan gula aren.', 'Warisan kesehatan leluhur Jawa yang diracik setiap subuh menggunakan rimpang segar hasil panen petani lokal. Kunyit Asam menyegarkan tubuh dan melancarkan metabolisme, sementara Beras Kencur meredakan pegal linu serta menambah kebugaran.', '/uwuh.jpg', '["/uwuh.jpg"]'::jsonb, '', 'Jamu kunyit asam dan beras kencur', true, '628816413617', 'Tersedia', '550 gram', 4.9, '["Dibuat Segar Setiap Hari Tanpa Pengawet","100% Rimpang Asli & Gula Jawa Murni","Nikmat Diminum Dingin dari Kulkas"]'::jsonb, '[{"label":"Isi Paket","value":"1 Botol Kunyit Asam (250ml) + 1 Botol Beras Kencur (250ml)"},{"label":"Ketahanan","value":"5 Hari di Dalam Kulkas"},{"label":"Asal Produk","value":"Dusun Singosaren, Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-48', 'Nasi Gurih Ingkung Ayam Kampung (Paket Besek)', 'Kuliner', 'Pawon Ingkung Wukirsari', 'Rp135.000 / besek utuh', 135000, 'Sajian sakral ayam kampung utuh dimasak santan rempah areh lengkap dengan nasi gurih dan lalapan.', 'Hidangan utama dalam tradisi kenduri, merti desa, dan syukuran masyarakat Jawa di Wukirsari. Menggunakan ayam kampung muda yang dimasak perlahan selama 4 jam dengan bumbu santan kental (areh), daun salam, serai, dan lengkuas hingga empuk meresap sampai ke tulang.', 'https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg', '["https://horizons-cdn.hostinger.com/73e774d8-1f03-44b2-ba9c-4491a99e3f2f/1af69d4a5467c90cf617e50609d8d0cb.jpg","/sawah.jpg"]'::jsonb, '', 'Ingkung ayam kampung besek', true, '628816413617', 'Tersedia', '1500 gram', 5, '["1 Ekor Ayam Kampung Asli Utuh","Lengkap Nasi Gurih, Sambal Bawang, Urap & Peyek","Dikemas Besek Bambu Cantik untuk Hantaran / Makan Bersama"]'::jsonb, '[{"label":"Porsi","value":"Cukup untuk 4 - 5 Orang"},{"label":"Pemesanan","value":"Pre-Order H-1 (Dimasak Dadakan agar Segar)"},{"label":"Kemasan","value":"Besek Bambu Besar Lapis Daun Pisang"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-49', 'Tiket & Paket Sunset Bukit Watu Gagak', 'Wisata Alam & Edukasi', 'Pokdarwis Watu Gagak', 'Rp25.000 / orang', 25000, 'Paket kunjungan menikmati panorama senja di puncak Watu Gagak lengkap dengan sajian wedang uwuh hangat.', 'Bukit Watu Gagak menyuguhkan lanskap batuan breksi vulkanik purba di ketinggian Wukirsari dengan latar belakang hamparan lembah hijau Sungai Oya dan siluet senja keemasan. Paket ini sudah termasuk tiket masuk kawasan, spot foto gardu pandang, dan segelas wedang uwuh hangat.', '/images/destinasi/watu-gagak.jpg', '["/images/destinasi/watu-gagak.jpg","/uwuh.jpg"]'::jsonb, '', 'Pemandangan alam Bukit Watu Gagak Wukirsari', true, '628816413617', 'Tersedia', '100 gram', 4.9, '["Spot Sunset Terbaik di Perbukitan Imogiri","Termasuk 1 Gelas Wedang Uwuh Hangat & Camilan Singkong","Akses Parkir Luas, Mushola & Gazebo Santai"]'::jsonb, '[{"label":"Waktu Terbaik","value":"15:30 - 18:15 WIB"},{"label":"Fasilitas","value":"Tiket Masuk, Parkir, Wedang Uwuh, Spot Foto"},{"label":"Lokasi","value":"Dusun Karangasem, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-50', 'Paket Piknik Keluarga Tepi Embung Wukirsari', 'Wisata Alam & Edukasi', 'Pengelola Embung Wukirsari', 'Rp120.000 / 4 orang', 120000, 'Paket bersantai keluarga di tepi telaga Embung Wukirsari lengkap tikar pandan, kudapan desa, dan pakan ikan.', 'Nikmati suasana damai telaga Embung Wukirsari yang dikelilingi hamparan sawah hijau dan perbukitan Imogiri. Paket piknik ini menyediakan tikar anyaman pandan, keranjang besek berisi thiwul, pisang rebus, kacang rebus, 4 wedang uwuh, serta pakan ikan untuk aktivitas edukasi anak.', '/images/destinasi/embung-wukirsari.jpg', '["/images/destinasi/embung-wukirsari.jpg","/uwuh.jpg"]'::jsonb, '', 'Suasana asri Embung Wukirsari', true, '628816413617', 'Tersedia', '500 gram', 4.8, '["Paket Hemat untuk 4 Orang Anggota Keluarga","Termasuk Sewa Tikar, Kudapan Tradisional & Pakan Ikan","Ramah Anak & Lansia dengan Jalur Jogging Track"]'::jsonb, '[{"label":"Kapasitas","value":"4 Orang"},{"label":"Jam Operasional","value":"07:00 - 17:30 WIB"},{"label":"Lokasi","value":"Kawasan Embung Desa Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-51', 'Paket Camping Ground Bukit Bego & Watu Gagak', 'Wisata Alam & Edukasi', 'Pokdarwis Alam Wukirsari', 'Rp175.000 / tenda', 175000, 'Sewa kavling dan tenda dome kapasitas 4 orang untuk berkemah menikmati gemerlap lampu kota Jogja di malam hari.', 'Rasakan sensasi bermalam di bawah taburan bintang perbukitan Wukirsari dengan pemandangan city-light Yogyakarta dari ketinggian. Tenda sudah dipasang rapi oleh tim lapangan lengkap dengan matras, lampu tenda, dan kayu bakar untuk api unggun bersama.', '/images/destinasi/bukit-bego.jpg', '["/images/destinasi/bukit-bego.jpg","/images/destinasi/watu-gagak.jpg"]'::jsonb, '', 'Camping di perbukitan Wukirsari', false, '628816413617', 'Tersedia', '1000 gram', 4.8, '["Tenda Dome Kapasitas 4 Orang Siap Pakai (Terima Beres)","Pemandangan City-Light & Sunrise Perbukitan","Keamanan 24 Jam & Kamar Mandi Bersih"]'::jsonb, '[{"label":"Fasilitas Tenda","value":"Tenda Double Layer, 4 Matras, Lampu Lentera"},{"label":"Check-in / Out","value":"15:00 WIB - 10:00 WIB Keesokan Harinya"},{"label":"Lokasi","value":"Area Camping Watu Gagak / Bukit Bego Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-52', 'Paket Edukasi Tani: Bajak Sawah & Tanam Padi', 'Wisata Alam & Edukasi', 'Dewi Tani Wukirsari', 'Rp65.000 / peserta', 65000, 'Program wisata edukasi anak sekolah dan keluarga belajar menanam padi (tandur) dan menangkap ikan di sawah.', 'Ajak buah hati dan siswa sekolah mengenal darimana nasi berasal melalui pengalaman langsung turun ke lumpur sawah organik Desa Wukirsari. Dipandu petani ramah, peserta belajar membajak sawah, menanam bibit padi (tandur), mengenal irigasi subak Jawa, hingga keseruan tangkap ikan dan makan siang di gubuk sawah.', '/images/destinasi/kampung-dolanan.jpg', '["/images/destinasi/kampung-dolanan.jpg","/sawah.jpg"]'::jsonb, '', 'Wisata edukasi tanam padi di sawah Wukirsari', true, '628816413617', 'Tersedia', '200 gram', 5, '["Pengalaman Autentik Turun ke Sawah bersama Petani","Sudah Termasuk Caping Bambu, Makan Siang & Bilas Bersih","Sangat Cocok untuk Outing Class TK, SD, SMP & Keluarga"]'::jsonb, '[{"label":"Durasi Kegiatan","value":"3 Jam (08:00 - 11:00 WIB)"},{"label":"Minimal Peserta","value":"10 Orang (Grup Sekolah / Keluarga)"},{"label":"Fasilitas","value":"Instruktur Petani, Caping, Makan Siang Desa, Kamar Bilas"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-53', 'Paket Jelajah Sepeda Onthel Susur Desa & Sawah', 'Wisata Alam & Edukasi', 'Komunitas Onthel Wukirsari', 'Rp85.000 / orang', 85000, 'Tur bersepeda santai menggunakan sepeda onthel klasik menyusuri pematang sawah, sungai, dan sentra kerajinan.', 'Nikmati udara pagi Desa Wisata Terbaik Dunia UNWTO dengan mengayuh sepeda onthel klasik lengkap dengan topi lurik/caping. Rute melintasi jalur pedesaan bebas polusi, jembatan gantung Sungai Oya, mampir melihat proses membatik di Giriloyo, dan berakhir dengan sarapan pecel kembang turi.', '/sawah.jpg', '["/sawah.jpg","/batik.jpg"]'::jsonb, '', 'Jelajah sepeda onthel di persawahan Wukirsari', true, '628816413617', 'Tersedia', '200 gram', 4.9, '["Sepeda Onthel Klasik Terawat + Topi Caping","Pemandu Lokal Berpengalaman & Dokumentasi Foto","Termasuk Sarapan Tradisional & Wedang Uwuh"]'::jsonb, '[{"label":"Jarak Tempuh","value":"± 7 km Jalur Datar & Pedesaan Asri"},{"label":"Waktu Mulai","value":"06:30 - 09:30 WIB"},{"label":"Fasilitas","value":"Sewa Sepeda, Guide, Sarapan, Air Mineral"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-54', 'Paket Outbound & Permainan Tradisional Anak (Dolanan Bocah)', 'Wisata Alam & Edukasi', 'Kampung Dolanan Wukirsari', 'Rp55.000 / anak', 55000, 'Wahana edukasi permainan tradisional Jawa seperti egrang bambu, bakiak, gasing, dakon, dan gobak sodor.', 'Menjauhkan anak-anak sejenak dari layar gawai dengan mengenalkan kembali kegembiraan permainan tradisional Jawa (dolanan bocah) yang melatih kerja sama tim, keseimbangan motorik, dan sportivitas di lapangan rumput terbuka Desa Wukirsari.', '/images/destinasi/kampung-dolanan.jpg', '["/images/destinasi/kampung-dolanan.jpg","/kipas.jpg"]'::jsonb, '', 'Permainan tradisional anak di Wukirsari', false, '628816413617', 'Tersedia', '150 gram', 4.9, '["Dipandu Kakak Fasilitator Ramah Anak","10+ Jenis Permainan Tradisional Bambu & Kayu","Bonus 1 Mainan Tradisional untuk Dibawa Pulang"]'::jsonb, '[{"label":"Durasi","value":"2,5 Jam"},{"label":"Fasilitas","value":"Alat Dolanan, Fasilitator, Snack Tradisional, Souvenir"},{"label":"Target Peserta","value":"Anak Usia 5 - 15 Tahun & Keluarga"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-55', 'Workshop Membatik Tulis Eksklusif (Bawa Pulang Karya)', 'Jasa & Budaya', 'Gazebo Wisata Batik Giriloyo', 'Rp75.000 / orang', 75000, 'Kursus singkat 2 jam belajar mencanting dan mewarnai batik tulis langsung bersama ibu pembatik Giriloyo.', 'Pengalaman budaya paling ikonik di Desa Wisata Wukirsari! Anda akan duduk berdampingan dengan pembatik tradisional Giriloyo, belajar memegang canting, menorehkan malam panas di atas kain mori, melakukan proses pewarnaan celup, hingga nglorod. Karya batik buatan Anda sendiri langsung dikeringkan dan dibawa pulang sebagai kenang-kenangan.', '/batik.jpg', '["/batik.jpg","/batik-1.jpg"]'::jsonb, '', 'Workshop belajar membatik di Giriloyo', true, '628816413617', 'Tersedia', '200 gram', 5, '["Dibimbing Langsung oleh Ibu Pembatik Tradisional","Hasil Karya Batik Milik Sendiri Langsung Dibawa Pulang","Termasuk Sajian Welcome Drink Wedang Uwuh"]'::jsonb, '[{"label":"Durasi Workshop","value":"2 - 2,5 Jam"},{"label":"Ukuran Kain Karya","value":"saputangan / Slayer 45 cm x 45 cm"},{"label":"Lokasi","value":"Gazebo Utama Kampung Batik Giriloyo"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-56', 'Workshop Tatah Sungging Wayang Kulit Pucung', 'Jasa & Budaya', 'Sanggar Wayang Pucung', 'Rp85.000 / orang', 85000, 'Kelas interaktif belajar memahat (menatah) dan mewarnai (menyungging) wayang kulit asli.', 'Kenali rahasia ketelitian seni kriya wayang kulit Dusun Pucung. Peserta akan diajarkan teknik dasar menggunakan pahat tatah besi di atas lembaran kulit kerbau serta teknik mewarnai gradasi tradisional (sungging) pada miniatur wayang atau pembatas buku kulit yang langsung menjadi milik peserta.', '/wayang.jpeg', '["/wayang.jpeg"]'::jsonb, '', 'Workshop tatah sungging wayang kulit', true, '628816413617', 'Tersedia', '200 gram', 4.9, '["Belajar Langsung dari Empu Pengrajin Wayang Pucung","Semua Bahan Kulit Kerbau & Cat Sungging Disediakan","Karya Selesai Langsung Dibawa Pulang"]'::jsonb, '[{"label":"Durasi","value":"2 Jam"},{"label":"Output Karya","value":"Miniatur Wayang Kulit / Kipas Kulit Sungging"},{"label":"Lokasi","value":"Dusun Pucung, Wukirsari, Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-57', 'Paket Wisata Ziarah & Sejarah Makam Raja-Raja Imogiri', 'Jasa & Budaya', 'Pemandu Wisata Budaya Pajimatan', 'Rp90.000 / pax', 90000, 'Tur bersejarah mendaki tangga Pajimatan Imogiri lengkap sewa busana adat abdi dalem dan pemandu sejarah.', 'Kompleks Makam Raja-Raja Mataram Imogiri (Pajimatan Girirejo) yang dibangun oleh Sultan Agung Hanyokrokusumo pada tahun 1632 memiliki tata aturan adat yang luhur. Paket ini memfasilitasi wisatawan dengan pemandu sejarah kompeten, sewa busana adat lengkap (kemben/peranakan bagi peziarah masuk cungkup), serta suguhan pecel kembang turi dan wedang uwuh seusai turun tangga.', '/images/destinasi/makam-imogiri.jpg', '["/images/destinasi/makam-imogiri.jpg","/images/destinasi/masjid-pajimatan.jpg"]'::jsonb, '', 'Wisata sejarah Makam Raja-Raja Imogiri', true, '628816413617', 'Tersedia', '300 gram', 5, '["Sudah Termasuk Sewa Pakaian Adat Ziarah (Kemben/Beskap Peranakan)","Didampingi Pemandu Sejarah Mataram Islam","Termasuk Kuliner Pecel Kembang Turi & Wedang Uwuh"]'::jsonb, '[{"label":"Jadwal Buka Cungkup","value":"Senin (10:00-12:00), Jumat (13:30-16:00), Minggu (10:00-12:00)"},{"label":"Kunjungan Pelataran","value":"Buka Setiap Hari untuk Wisata Sejarah & Arsitektur"},{"label":"Titik Kumpul","value":"Area Parkir Bawah Makam Raja Imogiri"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-58', 'Homestay Joglo Heritage Wukirsari (Per Malam)', 'Jasa & Budaya', 'Paguyuban Homestay Wukirsari', 'Rp250.000 / malam', 250000, 'Penginapan rumah tradisional Joglo dan Limasan Jawa yang asri, bersih, dan ramah keluarga.', 'Rasakan kehangatan hidup sebagai warga desa di Homestay Joglo Heritage Wukirsari. Bangunan kayu jati bergaya tradisional Jawa yang dilengkapi kamar tidur bersih ber-AC/kipas angin, kamar mandi dalam dengan air hangat, teras pendopo santai, serta sarapan pagi masakan ibu desa.', '/sawah.jpg', '["/sawah.jpg","/batik-1.jpg"]'::jsonb, '', 'Homestay Joglo tradisional di Wukirsari', false, '628816413617', 'Tersedia', '100 gram', 4.9, '["Suasana Pedesaan Tenang Dekat Sentra Batik Giriloyo","Sudah Termasuk Sarapan Pagi & Teh/Wedang Uwuh untuk 2 Orang","Kamar Mandi Bersih Standar CHSE Pariwisata"]'::jsonb, '[{"label":"Kapasitas Kamar","value":"2 Dewasa + 1 Anak"},{"label":"Fasilitas","value":"Kasur Queen, Wi-Fi, Kamar Mandi Dalam, Teras Joglo, Parkir"},{"label":"Check-in / Out","value":"14:00 WIB / 12:00 WIB"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-59', 'Sewa Busana Adat Jawa & Sesi Foto Heritage', 'Jasa & Budaya', 'Sanggar Rias Sekar Mataram', 'Rp150.000 / paket', 150000, 'Layanan sewa kebaya bludru/kutubaru dan surjan lurik lengkap jarik batik serta sesi foto di spot bersejarah.', 'Abadikan momen liburan Anda di Desa Wisata Wukirsari dengan mengenakan busana adat Jawa lengkap (Surjan Lurik/Beskap dan Blangkon untuk pria, Kebaya Kutubaru dan Sanggul/Hijab Jawa untuk wanita, lengkap dengan kain jarik batik tulis Giriloyo).', '/batik-2.png', '["/batik-2.png","/batik.jpg"]'::jsonb, '', 'Sewa busana adat Jawa di Wukirsari', true, '628816413617', 'Tersedia', '500 gram', 4.9, '["Koleksi Kebaya, Surjan & Jarik Batik Tulis Bersih Wangi","Dibantu Pemakaian Wiru Jarik Adat oleh Perias Desa","Bonus 10 File Foto Digital Edit di Spot Joglo / Tangga Imogiri"]'::jsonb, '[{"label":"Durasi Sewa","value":"3 Jam Pemakaian"},{"label":"Kelengkapan","value":"Atasan Adat, Jarik Batik, Blangkon/Aksesori, Selop"},{"label":"Lokasi Studio","value":"Kawasan Wisata Giriloyo, Wukirsari"}]'::jsonb);
INSERT INTO public.products (id, name, category, umkm, price, price_num, description, full_description, image_url, images, qris_image, image_alt, is_new, phone, stock_status, weight, rating, highlights, specifications) VALUES ('prod-60', 'Paket Studi Banding Desa Wisata Terbaik Dunia (UNWTO)', 'Jasa & Budaya', 'Pengelola Desa Wisata Wukirsari', 'Rp150.000 / peserta', 150000, 'Program kunjungan kerja dan studi tiru tata kelola Desa Wisata Wukirsari peraih penghargaan UNWTO.', 'Desa Wisata Wukirsari dinobatkan sebagai salah satu Best Tourism Villages oleh UNWTO (Organisasi Pariwisata Dunia PBB). Paket studi banding ini dirancang untuk pemerintah daerah, pengelola BUMDes, Pokdarwis, dan akademisi yang ingin mempelajari strategi pemberdayaan masyarakat, pelestarian budaya, serta digitalisasi UMKM melalui ekosistem WukirTech.', '/sawah.jpg', '["/sawah.jpg","/batik.jpg","/wayang.jpeg"]'::jsonb, '', 'Kunjungan studi banding Desa Wisata Wukirsari', true, '628816413617', 'Tersedia', '300 gram', 5, '["Narasumber Langsung Lurah / Ketua Pokdarwis & Pengelola WukirTech","Kunjungan Lapangan ke Sentra Batik, Wayang & BUMDes","Termasuk Materi Paparan, Sertifikat, Makan Siang Ingkung & Souvenir"]'::jsonb, '[{"label":"Minimal Rombongan","value":"20 Peserta (Instansi / Desa / Kampus)"},{"label":"Fasilitas Lengkap","value":"Pendopo Pertemuan, Sound System, Narasumber, Konsumsi, Goodie Bag"},{"label":"Lokasi","value":"Balai Kalurahan & Kawasan Desa Wisata Wukirsari"}]'::jsonb);

