INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-nguras-enceh', 'Upacara Adat Tradisi Nguras Enceh', '2026-07-03', '3 Juli 2026', '08:00 - 13:00 WIB', 'Makam Raja Imogiri, Pajimatan', 'Kompleks Makam Raja-Raja Mataram Pajimatan, Wukirsari, Imogiri', '[-7.9195,110.3965]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9195,110.3965', '/images/destinasi/nguras-enceh.jpg', 'Adat', 'Agenda Utama', 'Ritual tahunan bulan Sura menguras empat gentong pusaka peninggalan Sultan Agung bersama Abdi Dalem Yogyakarta dan Surakarta.', 'Upacara Adat Nguras Enceh dilaksanakan setiap Jumat Kliwon atau Selasa Kliwon di bulan Sura. Rangkaian acara dimulai dengan Kirab Siwur dari Pendopo Imogiri menuju Pajimatan, diikuti doa bersama Abdi Dalem Keraton Yogyakarta dan Surakarta sebelum menguras empat tempayan pusaka.', '["Kirab Budaya Siwur dari Pendopo Kapanewon Imogiri","Doa bersama Abdi Dalem Yogyakarta & Surakarta","Pengurasan empat gentong pusaka di Pajimatan"]'::jsonb, 'Pengunjung area cungkup mengenakan busana adat Jawa; pelataran bawah terbuka untuk umum dengan pakaian sopan.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-kirab-hari-jadi', 'Kirab Budaya Hari Lahir Kalurahan Wukirsari', '2026-08-17', '17 Agustus 2026', '08:00 - 17:00 WIB', 'Balai Kalurahan – Lapangan Demi', 'Start Balai Kalurahan Wukirsari menuju Lapangan Demi Wukirsari, Imogiri', '[-7.9088,110.415]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9088,110.4150', '/images/destinasi/kirab-budaya.jpg', 'Budaya', 'Agenda Utama', 'Arak-arakan bregada rakyat 16 padukuhan dan gunungan hasil bumi memeriahkan Hari Jadi Kalurahan Wukirsari.', 'Peringatan Hari Lahir Kalurahan Wukirsari diikuti kontingen seni dari 16 padukuhan dengan bregada prajurit rakyat, kirab gunungan hasil bumi, peragaan batik Giriloyo, kembul bujana ingkung, serta pagelaran wayang kulit malam hari.', '["Parade bregada rakyat & seni 16 padukuhan","Kirab & rayahan gunungan hasil bumi","Kembul bujana ingkung & wayang kulit malam"]'::jsonb, 'Disarankan hadir sebelum pukul 08:00 WIB untuk posisi menonton terbaik di sepanjang jalur kirab.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-4', 'Sedekah Alam & Merti Sumber Watu Gagak', '2026-11-22', '22 November 2026', '07:00 - 11:30 WIB', 'Bukit Watu Gagak, Karangasem', 'Puncak Bukit Watu Gagak, Padukuhan Karangasem, Kalurahan Wukirsari', '[-7.9062,110.4235]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9062,110.4235', '/images/destinasi/watu-gagak.jpg', 'Wisata Alam', 'Segera Hadir', 'Doa bersama, kenduri tumpeng, dan penanaman pohon konservasi di puncak Watu Gagak sebagai wujud syukur alam.', 'Sedekah Alam Watu Gagak merupakan wujud rasa syukur warga atas kelestarian sumber air dan kesuburan lahan. Acara meliputi kirab tumpeng hasil bumi ke puncak bukit, doa bersama, penanaman bibit pohon pelindung, dan sajian wedang uwuh.', '["Kirab tumpeng & kenduri hasil bumi","Penanaman bibit pohon konservasi air","Sajian wedang uwuh bersama pengunjung"]'::jsonb, 'Gunakan alas kaki yang nyaman untuk berjalan menanjak menuju pelataran puncak bukit.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-merti-desa-nov', 'Merti Desa & Gelar Seni Padukuhan', '2026-11-28', '28 November 2026', '13:00 - 21:00 WIB', 'Lapangan Demi Wukirsari', 'Kawasan Lapangan Demi, Jl. Imogiri Timur KM 14, Wukirsari', '[-7.9095,110.4162]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9095,110.4162', '/images/destinasi/kirab-gunungan.jpg', 'Adat', 'Segera Hadir', 'Upacara adat bersih desa yang dirangkai dengan pentas jathilan, gejog lesung, dan bazar kuliner tradisional.', 'Merti Desa mempertemukan warga dalam doa keselamatan desa yang dilanjutkan pentas seni kerakyatan seperti jathilan klasik, gejog lesung, dan pasar kuliner khas Imogiri.', '["Prosesi bersih desa & doa keselamatan","Pentas jathilan & gejog lesung warga","Bazar kuliner tradisional & UMKM lokal"]'::jsonb, 'Area parkir tersedia di sisi utara Lapangan Demi.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-festival-batik-giriloyo', 'Festival Batik Tulis Giriloyo', '2026-12-06', '6 Desember 2026', '09:00 - 16:00 WIB', 'Kampung Batik Giriloyo', 'Gazebo Utama Sentra Batik Tulis Giriloyo, Wukirsari, Imogiri', '[-7.9155,110.428]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9155,110.4280', '/batik.jpg', 'Budaya', 'Akan Datang', 'Gelar karya batik tulis pewarna alam, demo mencanting massal bersama pembatik Giriloyo, dan peragaan busana.', 'Festival di sentra batik tulis tertua Yogyakarta ini menampilkan aksi mencanting bersama ibu pembatik Giriloyo, peragaan busana motif klasik Mataram, serta pameran pewarnaan alam.', '["Mencanting bersama 100 pembatik Giriloyo","Peragaan busana batik klasik Mataram","Demonstrasi pewarnaan alam indigo & soga"]'::jsonb, 'Pengunjung dapat mengikuti sesi singkat belajar membatik di gazebo utama.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-wayang-pucung', 'Pagelaran Wayang & Tatah Sungging Pucung', '2026-12-13', '13 Desember 2026', '15:00 - 23:00 WIB', 'Sanggar Wayang Dusun Pucung', 'Sentra Kerajinan Wayang Kulit Padukuhan Pucung, Wukirsari', '[-7.9102,110.4205]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9102,110.4205', '/wayang.jpeg', 'Seni Pertunjukan', 'Akan Datang', 'Pameran kriya tatah sungging wayang kulit pada sore hari yang dilanjutkan pagelaran wayang kulit di malam hari.', 'Mengenalkan kerajinan tatah (memahat) dan sungging (pewarnaan) kulit kerbau karya empu Dusun Pucung, ditutup dengan pagelaran wayang kulit di pendopo terbuka.', '["Pameran tokoh wayang karya empu Pucung","Workshop mini tatah sungging kulit","Pagelaran wayang kulit malam hari"]'::jsonb, 'Lokasi berdekatan dengan akses wisata alam Grojogan Pucung.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-1', 'Festival Layang-layang & Dolanan', '2026-07-20', '20 Juli 2026', '14:00 - 17:30 WIB', 'Area Persawahan Wukirsari', 'Hamparan Sawah & Lapangan Terbuka Wukirsari, Imogiri', '[-7.9038,110.4135]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9038,110.4135', '/images/destinasi/kampung-dolanan.jpg', 'Budaya', 'Akan Datang', 'Lomba layang-layang hias tradisional di area persawahan Wukirsari bersama arena permainan tradisional anak.', 'Kompetisi layang-layang hias bermotif batik dan tokoh pewayangan yang digelar di area persawahan terbuka, dilengkapi permainan egrang, bakiak, dan gasing bambu.', '["Lomba layang-layang hias tradisional","Arena permainan dolanan anak gratis","Panorama senja kawasan persawahan"]'::jsonb, 'Disarankan membawa topi atau pelindung matahari untuk aktivitas sore.');
INSERT INTO public.events (id, title, date, date_display, time, location, venue_detail, coordinates, google_maps_url, image, category, status, description, full_description, highlights, tips) VALUES ('evt-5', 'Pentas Seni & Lampion Embung', '2026-12-31', '31 Desember 2026', '19:00 - 24:00 WIB', 'Embung Wukirsari', 'Panggung Terbuka Kawasan Embung Wukirsari, Imogiri, Bantul', '[-7.9045,110.416]'::jsonb, 'https://www.google.com/maps/search/?api=1&query=-7.9045,110.4160', '/images/destinasi/embung-wukirsari.jpg', 'Seni Pertunjukan', 'Akan Datang', 'Pertunjukan musik akustik, tari tradisional pemuda desa, kuliner angkringan, dan penyalaan lampion di tepi embung.', 'Acara malam pergantian tahun yang menghadirkan pertunjukan seni pemuda desa, festival angkringan kuliner khas Imogiri, dan penyalaan lampion di tepi telaga Embung Wukirsari.', '["Pentas tari tradisional & musik akustik","Festival angkringan wedang uwuh","Penyalaan lampion di tepi telaga"]'::jsonb, 'Kenakan pakaian hangat karena udara malam di area embung cukup sejuk.');

