-- 8. INSERT DATA BERITA DESA (2 baris)
-- ============================================================================
INSERT INTO public.news (id, tag, category, title, subtitle, date, read_time, location, author, image, gallery, highlights, summary, content) VALUES ('news-nguras-enceh', 'Tradisi Sura', 'Warisan Budaya Takbenda', 'Tradisi Sakral ''Nguras Enceh'' di Makam Raja-Raja Mataram Imogiri', 'Warisan Sultan Agung sejak abad ke-17 yang mempertemukan Abdi Dalem Yogyakarta dan Surakarta dalam satu prosesi khidmat.', 'Jumat Kliwon, Bulan Sura', '4 menit baca', 'Pajimatan Imogiri, Wukirsari', 'Tim Redaksi WukirTech', '/images/destinasi/nguras-enceh.jpg', '["/images/destinasi/nguras-enceh.jpg","/images/destinasi/enceh-siyem.jpg","/images/destinasi/makam-imogiri.jpg"]'::jsonb, '["Kirab Siwur & Bregada dari Pendopo Imogiri","Pengurasan 4 Gentong Pusaka peninggalan Sultan Agung","Diakui sebagai Warisan Budaya Takbenda Indonesia"]'::jsonb, 'Upacara adat tahunan setiap Jumat Kliwon atau Selasa Kliwon di bulan Sura untuk menguras empat gentong pusaka di Kompleks Makam Raja Imogiri sebagai simbol kebersamaan dan pelestarian tradisi Mataram.', '["WUKIRSARI, IMOGIRI — Setiap memasuki bulan Sura, kawasan Pajimatan Makam Raja-Raja Mataram di Kalurahan Wukirsari dipadati peziarah dan wisatawan yang menyaksikan Upacara Adat Nguras Enceh (Nguras Kongsi).","Sehari sebelumnya digelar Kirab Budaya Siwur dari Pendopo Kapanewon Imogiri menuju pelataran tangga Makam Raja Imogiri dengan iringan bregada prajurit rakyat, gejog lesung, dan gunungan hasil bumi.","Pada puncak acara, Abdi Dalem dari Kasultanan Yogyakarta dan Kasunanan Surakarta bersama-sama memanjatkan doa lalu menguras empat tempayan pusaka peninggalan Sultan Agung: Kyai Danumaya, Kyai Danumurti, Nyai Siyem, dan Nyai Mendung."]'::jsonb);
INSERT INTO public.news (id, tag, category, title, subtitle, date, read_time, location, author, image, gallery, highlights, summary, content) VALUES ('news-kirab-wukirsari', 'Hari Jadi Desa', 'Kirab Budaya', 'Kirab Budaya Hari Lahir Kalurahan Wukirsari & Gunungan 16 Padukuhan', 'Perayaan tahunan yang menyatukan seluruh padukuhan di Wukirsari lewat arak-arakan bregada rakyat, seni tradisi, dan bazar UMKM.', 'Tahunan • Hari Lahir Desa', '4 menit baca', 'Balai Kalurahan – Lapangan Demi', 'Pokdarwis Wukirsari', '/images/destinasi/kirab-budaya.jpg', '["/images/destinasi/kirab-budaya.jpg","/images/destinasi/kirab-gunungan.jpg","/wayang.jpeg"]'::jsonb, '["Parade Bregada & Kontingen Seni 16 Padukuhan","Kirab Gunungan Hasil Bumi & Kembul Bujana Ingkung","Gelar Batik Giriloyo & Pagelaran Wayang Kulit"]'::jsonb, 'Ribuan warga dari 16 padukuhan menampilkan bregada prajurit, gunungan hasil bumi, dan kesenian daerah sepanjang jalur kirab sebagai ungkapan syukur Hari Lahir Kalurahan Wukirsari.', '["WUKIRSARI, IMOGIRI — Peringatan Hari Lahir Kalurahan Wukirsari dimeriahkan Kirab Budaya Agung yang diikuti perwakilan seni serta potensi UMKM dari seluruh 16 padukuhan.","Prosesi dibuka di halaman Balai Kalurahan Wukirsari sebelum rombongan bregada, gunungan hasil bumi, pembatik Giriloyo, dan pengrajin wayang Pucung berjalan menuju Lapangan Demi Wukirsari.","Acara ditutup dengan doa bersama, pembagian gunungan hasil bumi, Kembul Bujana Ingkung Ayam Kampung, serta pagelaran wayang kulit pada malam hari."]'::jsonb);

