INSERT INTO public.vr_tour_config (id, title, subtitle, theme, start_scene_id) VALUES ('default', 'VR Tour 360° Desa Wisata Wukirsari', 'Jelajah virtual interaktif cagar budaya dan alam Wukirsari, Imogiri', 'Cultural Heritage & Nature', 'scene-imogiri');
INSERT INTO public.vr_scenes (id, name, category, image, description, initial_yaw, initial_pitch, hotspots, sort_order) VALUES ('scene-imogiri', 'Ruangan A — Pelataran & Tangga Makam Raja Imogiri', 'Sejarah & Cagar Budaya', '/images/destinasi/makam-imogiri.jpg', 'Gerbang utama dan tangga bersejarah Astana Pajimatan Himagiri peninggalan Sultan Agung (1632).', 0, 5, '[{"id":"hs-imogiri-to-giriloyo","type":"nav","yaw":38,"pitch":-4,"label":"Masuk ke Kampung Batik Giriloyo","targetSceneId":"scene-giriloyo"},{"id":"hs-imogiri-to-watugagak","type":"nav","yaw":-45,"pitch":2,"label":"Menuju Bukit Watu Gagak","targetSceneId":"scene-watugagak"},{"id":"hs-imogiri-info-tangga","type":"info","yaw":0,"pitch":12,"title":"Tangga Pajimatan 345 Anak Tangga","description":"Tangga batu bersejarah yang menghubungkan pelataran Masjid Kagungan Dalem menuju cungkup makam raja-raja Mataram.","image":"/images/destinasi/masjid-pajimatan.jpg"},{"id":"hs-imogiri-info-enceh","type":"info","yaw":18,"pitch":-8,"title":"Empat Enceh Pusaka","description":"Tempat pelaksanaan tradisi tahunan Nguras Enceh setiap bulan Sura.","image":"/images/destinasi/enceh-siyem.jpg"}]'::jsonb, 0);
INSERT INTO public.vr_scenes (id, name, category, image, description, initial_yaw, initial_pitch, hotspots, sort_order) VALUES ('scene-giriloyo', 'Ruangan B — Gazebo Kampung Batik Tulis Giriloyo', 'Kriya & Budaya', '/batik.jpg', 'Sentra batik tulis klasik keraton di lereng perbukitan Imogiri yang dikelola ratusan pembatik perempuan.', 0, 0, '[{"id":"hs-giriloyo-to-imogiri","type":"nav","yaw":-50,"pitch":-5,"label":"Kembali ke Makam Raja Imogiri","targetSceneId":"scene-imogiri"},{"id":"hs-giriloyo-to-pucung","type":"nav","yaw":45,"pitch":-3,"label":"Masuk ke Grojogan & Sanggar Pucung","targetSceneId":"scene-pucung"},{"id":"hs-giriloyo-info-canting","type":"info","yaw":5,"pitch":-10,"title":"Proses Mencanting Malam Panas","description":"Setiap helai kain batik tulis Giriloyo dikerjakan secara manual menggunakan canting tembaga dan pewarna alam.","image":"/batik-1.jpg"}]'::jsonb, 1);
INSERT INTO public.vr_scenes (id, name, category, image, description, initial_yaw, initial_pitch, hotspots, sort_order) VALUES ('scene-watugagak', 'Ruangan C — Gardu Pandang Bukit Watu Gagak', 'Wisata Alam', '/images/destinasi/watu-gagak.jpg', 'Puncak tebing batuan breksi purba dengan panorama senja dan lembah Sungai Oya dari ketinggian.', 0, 0, '[{"id":"hs-watugagak-to-imogiri","type":"nav","yaw":-40,"pitch":-6,"label":"Kembali ke Makam Raja Imogiri","targetSceneId":"scene-imogiri"},{"id":"hs-watugagak-to-pucung","type":"nav","yaw":35,"pitch":-4,"label":"Menuju Grojogan Pucung","targetSceneId":"scene-pucung"},{"id":"hs-watugagak-info-oya","type":"info","yaw":-10,"pitch":8,"title":"Panorama Lembah Sungai Oya","description":"Titik terbaik menikmati matahari terbenam dan lokasi ritual tahunan Sedekah Alam.","image":"/images/destinasi/sungai-oya.jpg"}]'::jsonb, 2);
INSERT INTO public.vr_scenes (id, name, category, image, description, initial_yaw, initial_pitch, hotspots, sort_order) VALUES ('scene-pucung', 'Ruangan D — Air Terjun Grojogan & Sanggar Wayang Pucung', 'Alam & Seni Tradisi', '/images/destinasi/grojogan-pucung.jpg', 'Kawasan air terjun alami bertingkat di Dusun Pucung yang berdekatan dengan sentra tatah sungging wayang kulit.', 0, 0, '[{"id":"hs-pucung-to-giriloyo","type":"nav","yaw":-35,"pitch":-5,"label":"Kembali ke Kampung Batik Giriloyo","targetSceneId":"scene-giriloyo"},{"id":"hs-pucung-to-imogiri","type":"nav","yaw":40,"pitch":-5,"label":"Menuju Makam Raja Imogiri","targetSceneId":"scene-imogiri"},{"id":"hs-pucung-info-wayang","type":"info","yaw":12,"pitch":5,"title":"Kriya Wayang Kulit Pucung","description":"Dusun Pucung merupakan rumah bagi para empu pembuat wayang kulit kerbau berstandar keraton.","image":"/wayang.jpeg"}]'::jsonb, 3);